-- Generated from the reviewed CSV drafts. Review source references before production publishing.
on conflict (id) do update set name = excluded.name, pinyin = excluded.pinyin, meaning = excluded.meaning, example = excluded.example, category = excluded.category, source_ref = excluded.source_ref, review_status = excluded.review_status, status = excluded.status;

on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation, source = excluded.source, source_ref = excluded.source_ref, difficulty = excluded.difficulty, status = excluded.status, content_status = excluded.content_status, reviewed_at = excluded.reviewed_at;

