insert into public.idioms (id,name,pinyin,meaning,example,category,source_ref,review_status,status) values
('source-001','阿鼻地狱','ā bí dì yù','阿鼻梵语的译音，意译为无间”，即痛苦无有间断之意。常用来比喻黑暗的社会和严酷的牢狱。又比喻无法摆脱的极其痛苦的境地。','但也有少数意志薄弱的……逐步上当，终至堕入～。★《上饶集中营·炼狱杂记》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-002','阿姑阿翁','ā gū ā wēng','阿名词的前缀。姑丈夫的母亲。翁丈夫的父亲。指公公婆婆。','既然如此，你我两个，便学个不痴不聋的～。★《儿女英雄传》二三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-003','阿娇金屋','ā jiāo jīn wū','阿娇指汉武帝刘彻的姑母（长公主刘娇）的女儿。原指汉武帝刘彻要用金屋接纳阿娇为妇。这里泛指美丽高贵的女子。','～原相配，太其玉镜宁无时？★明·周履靖《锦笺记·诒婚》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-004','阿猫阿狗','ā māo ā gǒu','旧时人们常用的小名。引申为任何轻贱的，不值得重视的人或著作。','在德国无论～见面，一律互相举手高喊希特勒万岁”。★邹韬奋《法西斯作风的罪恶》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-005','阿弥陀佛','ē mí tuó fó','佛教语，信佛的人用作口头诵颂的佛号，表示祈祷祝福或感谢神灵的意思。','和尚念经，～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-006','阿毗地狱','ā pí dì yù','阿毗梵语的译音，意译为无间”，即痛苦无有间断之意。常用来比喻黑暗的社会和严酷的牢狱。又比喻无法摆脱的极其痛苦的境地。','生前不曾修福，死堕～。★《敦煌变文集·妙法莲花经讲经文》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-007','阿其所好','ē qí suǒ hào','阿曲从；其他的；好爱好。指为取得某人的好感而迎合他的爱好。','吾何能～为？★鲁迅《坟·摩罗诗力说》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-008','阿谀逢迎','ē yú féng yíng','阿谀用言语恭维别人；逢迎迎合别人的心意。奉承，拍马，讨好别人。','其时京师有一流棍，名叫李光，专一～，谄事令孜。★明·凌濛初《初刻拍案惊奇》卷二十二','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-009','阿谀取容','ē yú qǔ róng','阿谀曲意逢迎；取容取悦于人。谄媚他人，以取得其喜悦。','且王髈等～，蔽贤窃位。★明·冯梦龙《东周列国志》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-010','哀哀父母','āi āi fù mǔ','可哀呀可哀，我的父母啊！原指古时在暴政下的人民终年在外服劳役，对父母病痛、老死不能照料而悲哀。','咱人有子方知不孝娘，岂不问～情肠！★元·无名氏《小张屠》第一折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-011','哀哀欲绝','āi āi yù jué','哀哀极度悲哀；绝断气，死。形容极其悲痛。','那安太太进门，一眼便看见姑娘，～的跪在那里……便一直的奔了姑娘去。★清·文康《儿女英雄传》第二十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-012','哀兵必胜','āi bīng bì shèng','原意是力量相当的两军对阵，悲愤的一方获得胜利◇指因受欺侮而奋起抵抗的军队，必定能取胜。','不，～！不要乐，要哀，何小姐能弹《易水吟》的谱子吗？★张恨水《啼笑因缘续集》第十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-013','哀而不伤','āi ér bù shāng','哀悲哀；伤伤害。忧愁而不悲伤，形容感情有节制；另形容诗歌、音乐优美雅致，感情适度。比喻做事没有过头也无不及。','她喜欢打扮，愿意有朋友，可是这都不过是一些小小的、～的、青春的游戏。★老舍《四世同堂》四十三','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-014','哀感顽艳','āi gǎn wán yàn','顽愚顽。原意是指内容凄切，文辞华丽，使愚笨和聪慧的人同样受感动◇多用来指艳情的小说、戏曲、电影中的感人情节。','这封信却是骈四骈六的，足有三千多字，写得异常的～。★清·吴趼人《二十年目睹之怪现状》第七十一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-015','哀鸿遍地','āi hóng biàn dì','哀鸿哀鸣的鸿雁。比喻啼饥号寒的灾民。比喻在天灾人祸中到处都是流离失所、呻吟呼号的饥民。','天涯吟望，～，都成愁侣。★黄侃《水龙吟·秋花》词','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-016','哀鸿遍野','āi hóng biàn yě','哀鸿哀鸣的鸿雁。比喻啼饥号寒的灾民。比喻在天灾人祸中到处都是流离失所、呻吟呼号的饥民。','我记得历史上的罗马何等殷阗繁盛，怎么今日却是～，春燕无归，满眼凄惶。★清·梁启超《新罗马》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-017','哀毁骨立','āi huǐ gǔ lì','哀悲哀；毁损坏身体；骨立形容极瘦，只剩下骨架。旧时形容在父母丧中因过度悲伤而瘦得只剩一把骨头。','众亲戚已到，商量在本族亲房立了一个儿子过来，然后大殓治丧。蘧公子～，极倦子之谊。★清·吴敬梓《儒林外史》第十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-018','哀丝豪竹','āi sī háo zhú','丝指弦乐器；竹指管乐器；豪竹粗大的竹管制成的乐器。形容管弦乐声的悲壮动人。','～颂英烈，此是北昆跃进花。★茅盾《观北昆剧院初演〈红霞〉》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-019','挨肩搭背','āi jiān dā bèi','挨肩肩和肩相靠。搭背手搭在别人背上。形容极其亲昵的样子。','看她俩挨肩搭背的样子，就知道是一对好朋友。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-020','挨门挨户','āi mén āi hù','挨按照顺序。按照住户的顺序一家也不漏。同挨门逐户”。','她［一丈青大娘］又跑遍沿河几个村落，～乞讨零碎布头儿，给何满子缝了一件五光十色的百家衣。★刘绍棠《蒲柳人家》一','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-021','矮人观场','ǎi rén guān cháng','比喻只知道附和别人，自己没有主见。也比喻见识不广。','最有识见之客，亦作～。★清·李渔《闲情偶寄·演习·选剧》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-022','矮人看场','ǎi rén kàn chǎng','比喻只知道附和别人，自己没有主见。也比喻见识不广。','是真是假，要弄个明白，不能～，人云亦云。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-023','矮子看戏','ǎi zǐ kàn xì','比喻只知道附和别人，自己没有主见。也比喻见识不广。','～何曾见，都是随人说短长。★清·赵翼《诗论》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-024','蔼然可亲','ǎi rán kě qīn','蔼然对人和善的样子。形容态度和气，使人愿意接近。','早有那般世谊同年，见他翩翩风度，～，都愿和他亲近进来了。★清·文康《儿女英雄传》第三十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-025','爱不忍释','ài bù rěn shì','释放下。对所喜欢的物品，爱得拿在手里久久不肯放下。','得见钱唐陈小云司马《香畹楼忆语》钞本一种，～，亟问假归，手录展玩。★清·王维鋆《香畹楼忆语序一》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-026','爱才如渴','ài cái rú kě','才贤才，人才。爱慕贤才，急欲求得，就象口渴急于喝水一样。','宫保～，兄弟实在钦佩的。★清·刘鹗《老残游记》六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-027','爱才如命','ài cái rú mìng','才贤才，人才。爱慕贤才，急欲求得，就象生命一样重要。','本帅～，何必过谦？★《说岳全传》第三一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-028','爱才若渴','ài cái ruò kě','才贤才，人才。爱慕贤才，急欲求得，就象口渴急于喝水一样。','他们发现了佳人并非因为‘～’而做婊子的，佳人只为的是钱。★鲁迅《上海文艺之一瞥》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-029','爱财如命','ài cái rú mìng','把钱财看得跟生命一样重要。形容极端吝啬。','那个人极端自私，～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-030','爱富嫌贫','ài fù xián pín','嫌弃贫穷，喜爱富有。指对人的好恶以其贫富为准。','方信道贫居闹市无人问，富在深山有远亲。如今人～。★明·无名氏《贫富兴衰》第二折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-031','爱礼存羊','ài lǐ cún yáng','由于爱惜古礼，不忍使它废弛，因而保留古礼所需要的祭羊。比喻为维护根本而保留有关仪节。','本朝监学之法，虽参以天下之士，而于国子加厚矣。盖～，以有待也。★宋·陈亮《国子》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-032','爱民如子','ài mín rú zǐ','旧时称赞某些统治者爱护百姓，就象爱护自己的子女一样。','一路地方官员馈送礼物，岳爷始终不受……只是吩咐他们学好做官，须要爱民如子，无负朝廷。★清·钱彩《说岳全传》第四八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-033','爱莫能助','ài mò néng zhù','爱爱惜；莫不。虽然心中关切同情，却没有力量帮助。','收到各处的回信，只是写些～”之类的抱歉话。★叶圣陶《得失》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-034','爱莫之助','ài mò zhī zhù','爱爱惜；莫不。虽然心中关切同情，却没有力量帮助。','晚虽家事不如初，而亲戚故旧之急难，族人子弟之美事，～，每致其倦倦之意，而人人常信之。★宋·陈亮《喻夏卿墓志铭》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-035','爱钱如命','ài qián rú mìng','某些人贪爱钱财就像吝啬生命一样。形容十分贪婪、刻薄。','1942年我在成都重见她的时候，她已经成了一个～的可笑的胖女人。★巴金《谈》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-036','爱人以德','ài rén yǐ dé','爱人爱护别人；德德行。按照道德标准去爱护人。泛指对人不偏私偏爱，不姑息迁就。','轼闻琦语，曰公可谓～矣。”★《宋史·苏轼传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-037','爱屋及乌','ài wū jí wū','因为爱一个人而连带爱他屋上的乌鸦。比喻爱一个人而连带地关心到与他有关的人或物。','子存宠上了小老婆，未免～”，把他也看得同上客一般。★清·吴趼人《二十年目睹之怪现状》第十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-038','爱惜羽毛','ài xī yǔ máo','羽毛比喻人的声望。比喻为珍惜自己的名声，行事十分谨慎。','灰鹤与他都是高傲的，～的，而他与它们的高傲只是一种姿态而已，没有用，没有任何的用。★老舍《四世同堂》五十','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-039','暧昧不明','ài mèi bù míng','暧昧含糊，不清楚。指不清不楚，不明不白。形容态度不明朗，关系不鲜明。','武汉国民政府和当权军人对于这叛变采取了～的态度，办求化大事为小事”。★陶菊隐《北洋军阀统治时期史话》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-040','暧昧之情','ài mèi zhī qíng','行为不光明，内有不可告人的隐情。也指男女互相爱悦可能的私事。','而孤男寡女并外一室，不无～。★清·明教中人《好逑传》第十五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-041','安不忘危','ān bù wàng wēi','在安全的时候不忘记危难。意思是时刻谨慎小心，提高警惕。','何小姐是从苦境里过来的，如今得地身安，安不忘危，立志要成全起这份人家，立番事业。★清·文康《儿女英雄传》第三十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-042','安步当车','ān bù dàng chē','安安详，不慌忙；安步缓缓步行。以从容的步行代替乘车。','每日到局只要把照例的公事办完，立刻回公馆吃饭，一到下午，便一个人～，出门逍遥自在去了。★清·李宝嘉《中国现在记》第七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-043','安常处顺','ān cháng chǔ shùn','安习惯于；处居住，居于；顺适合，如意。习惯于平稳的日子，处于顺利的境遇中。','～，以为社会一健全分子，以徐徐发达，人尽能之，岂待我辈。★清·梁启超《中国前途之希望与国民责任》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-044','安常守故','ān cháng shǒu gù','习惯于日常的平稳生活，保守旧的一套。指守旧不知变革。','他长期以来～，缺乏锻炼，因而经不起挫折。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-045','安常习故','ān cháng xí gù','习习惯；故旧例。安于常规，习惯旧例。形容按照常规和老套办事，守旧而不思变革。','彼～之流。★清·魏源《治篇七》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-046','安车蒲轮','ān chē pú lún','让被征请者坐在安车上，并用蒲叶包着车轮，以便行驶时车身更为安稳。表示皇帝对贤能者的优待。','申公待聘，～。★明·张岱《寿周霞城八十》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-047','安堵如故','ān dǔ rú gù','堵墙壁，居所。故原来的。像原来一样相安无事。','当涂、徽州、得以～，皆先生一谑之力也。★清·张岱《王谑庵先生传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-048','安分守己','ān fèn shǒu jǐ','分本分。规矩老实，守本分，不做违法的事。','从此养好了，可要安分守己，再别胡行乱闹了。★清·曹雪芹《红楼梦》第七十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-049','安富恤贫','ān fù xù pín','恤救济。使富有的人安定，贫穷的人得到救济。','各国都应采取一些～的措施，以保障社会的安定。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-050','安富恤穷','ān fù xù qióng','安定富有者，振济贫苦者。指统治者治国安民之道。','损不失富，优可赈穷，此乃古者～之善经，不可舍也。★唐·陆贽《均节赋税恤百姓六条》六','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-051','安富尊荣','ān fù zūn róng','安安逸；富富有；尊尊贵；荣荣耀。安定富足，尊贵荣华。也指安于富裕安乐的生活。','主仆上下都是～，运筹谋画的竟无一个。★清·曹雪芹《红楼梦》第二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-052','安居乐业','ān jū lè yè','安安定；乐喜爱，愉快；业职业。指安定愉快地生活和劳动。','一家正～，不想安禄山兵乱，潼关失守，天子西幸。★明·冯梦龙《醒世恒言》卷六','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-053','安老怀少','ān lǎo huái shào','安安顿；怀关怀。尊重老人，使其安逸；关怀年轻人，使其信服。','诚为枉法营私，原王章所不宥；要知～，亦圣道之大同。★清·文康《儿女英雄传》第三十五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-054','安民告示','ān mín gào shì','安定人心的布告。现也指把要商量的或要办的事情预先通知大家。','开会要事先通知，像出～一样，让大家知道要讨论什么问题，解决什么问题，并且早做准备。★毛泽东《党委会的工作方法》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-055','安内攘外','ān nèi rǎng wài','攘排除。原就药的疗效而言◇多指安定内部，排除外患。','～之大经，富国强兵之远略。★孙中山《上李鸿章书》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-056','安贫乐道','ān pín lè dào','道主张，思想。安于贫穷，以坚持自己的信念为乐。旧时士大夫所主张的为人处世之道。','劝人～是古今治国平天下的大经络，开过的方子也很多，但都没有十全大补的功效。★鲁迅《花边文学·安贫乐道法》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-057','安然无恙','ān rán wú yàng','恙病。原指人平安没有疾病。现泛指事物平安未遭损害。','只求处士每岁元旦，作一朱幡，上图日月五星之文，立于苑东，吾辈则安然无恙矣。★明·冯梦龙《醒世恒言》第四卷','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-058','安忍无亲','ān rěn wú qīn','安忍习于残忍，不以为异。安心于做残忍的事情，因而无所谓亲人。','李世绩之～也，置父于窦建德之刃下而不恤。★清·王夫之《读通鉴论·唐高宗》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-059','安如盘石','ān rú pán shí','安安稳；盘石大石头。像盘石一样安稳不动。形容非常稳固，不可动摇。','立宪国皇室所以～者，道皆在是也。★清·梁启超《责任内阁释义》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-060','安如磐石','ān rú pán shí','磐石大石头。如同磐石一般安然不动。形容非常稳固。','立宪国皇室所以～，道皆在是也。★清·梁启超《责任内阁释义》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-061','安身立命','ān shēn lì mìng','安身在某处安下身来；立命精神有所寄托。指生活有着落，精神有所寄托。','那里是镇守边庭，用人之际，足可以～。★明·施耐庵《水浒全传》第二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-062','安土重迁','ān tǔ zhòng qiān','土乡土；重看得重，不轻易。安于本乡本土，不愿轻易迁移。','自古道～。”说了离乡背井，那一个不怕的。★明·冯梦龙《东周列国志》第七十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-063','安危相易','ān wēi xiāng yì','易变易，转变。平安与危难互为因果，相互转换。','～，祸福相生”，事之由妄想而成者，岂独胚胎然哉？★章炳麟《菌说》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-064','安心乐意','ān xīn lè yì','原指心情安宁，情绪愉快◇多指内心情愿，十分愉快。','自己便～，在寺里住下。★清·吴趼人《九命奇冤》第二十五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-065','安营下寨','ān yíng xià zhài','安、下建立，安置；寨防守用的栅栏。指部队驻扎下来。也比喻建立临时的劳动或工作基地。','操曰吾料吕布有勇无谋，不足虑也。”教且～，再做商议。★明·罗贯中《三国演义》第十一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-066','安营扎寨','ān yíng zhā zhài','安、扎建立，安置；寨防守用的栅栏。指部队驻扎下来。也比喻建立临时的劳动或工作基地。','打什么地方进兵，打什么地方退兵，什么地方可以～，什么地方可以埋伏，指手画脚的讲了一通。★清·李宝嘉《官场现形记》第十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-067','安枕而卧','ān zhěn ér wò','放好枕头睡大觉。比喻太平无事，不必担忧。','孔子见疏，必弃鲁国而适他国，君可～矣。★明·冯梦龙《东周列国志》第七十九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-068','安之若素','ān zhī ruò sù','安安然，坦然；之代词，指人或物；素平常。安然相处，和往常一样，不觉得有什么不合适。','第二天宝小姐酒醒，很觉得过意不去◇来彼此熟了，见瞿太太常常如此，也就～了。★清·李宝嘉《官场现形记》第三十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-069','鞍马劳顿','ān mǎ láo dùn','顿困顿。骑马赶路过久，劳累疲困。形容旅途劳累。','恐王侄一路远来，～，故令王侄回营安歇。★清·钱彩《说岳全传》第四二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-070','鞍马之劳','ān mǎ zhī láo','鞍马鞍子和马，指长途跋涉或打仗。形容旅途或战斗的劳苦。','唐铉说此话以后再说。请到那边入座，少饮几杯水酒，以解二位～。”★姚雪垠《李自成》第三卷第三十四章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-071','按兵不动','àn bīng bù dòng','按止住。使军队暂不行动。现也比喻暂不开展工作。','又听得寨前炮响，史文恭～，只要等他入来，塌了陷坑，山后伏兵齐起，接应捉人。★明·施耐庵《水浒全传》第六十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-072','按步就班','àn bù jiù bān','指按照条理或遵循一定的程序。参见按部就班”。','学校却，没有这弊病。★鲁迅《书信集·致陶亢德》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-073','按部就班','àn bù jiù bān','部、班门类，次序；就归于。按照一定的步骤、顺序进行。也指按老规矩办事，缺乏创新精神。','但黄公俊的祖父，他开始读了书，象一般读书人似的，他～的要将八股型的才学，货与帝王家”。★郑振铎《黄公俊之最后》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-074','按图索骥','àn tú suǒ jì','索找；骥良马。按照画像去寻求好马。比喻墨守成规办事；也比喻按照线索去寻求。','每见一班～者，多失于骊黄牝牡。★明·赵沺《葬书问对》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-075','按图索骏','àn tú suǒ jùn','指按照画像去寻求好马。比喻墨守成规办事；也比喻按照线索去寻求。参见按图索骥”。','虽部胥掌阙簿者，亦不过～。★宋·周密《癸辛杂识续集下·卖阙沈官人》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-076','案无留牍','àn wú liú dú','桌案上没有积压的公文。形容办理公务干练、及时。','一应公事，张令都听他决断。真是～，狱无冤刑，民心大悦。★清·黄小配《洪秀全演义》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-077','暗度陈仓','àn dù chén cāng','指正面迷惑敌人，而从侧翼进行突然袭击。亦比喻暗中进行活动。陈仓，古县名，在今陕西省宝鸡市东，为通向汉中的交通孔道。','臣已算定今番诸葛亮必效韩信～之计。★《三国演义》第九六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-078','暗度金针','àn dù jīn zhēn','度通渡”，过渡，引申为传授◇用于比喻秘诀。又借指幕后交易。','日本政府，向来主张～，我国虽尚守中立，未曾加入协约团体，但日本如此举动，本使也很不赞成。★蔡东藩《民国演义》第六十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-079','暗渡陈仓','àn dù chén cāng','渡越过；陈仓古县名，在今陕西省宝鸡市东。比喻用造假象的手段来达到某种目的。也隐喻男女私通。','孤家用韩信之计，明修栈道，～，攻定三秦，动取五国。★元·无名氏《气英布》第一折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-080','暗箭伤人','àn jiàn shāng rén','放冷箭伤害人。比喻暗地里用某种手段伤害人。','有荼毒生灵的强盗，有～的强盗。★清·李汝珍《镜花缘》第五十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-081','暗室不欺','àn shì bù qī','在没有人看见的地方，也不做见不得人的事。','知县生平～，既读孔、孟之书，怎敢行盗跖之事？★明·冯梦龙《醒世恒言》卷十三','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-082','暗室欺心','àn shì qī xīn','在黑暗的屋子里昧着良心做坏事。指偷偷地做坏事。','方信道暗室亏心，难逃他神目如电。★《元曲选·无名氏三》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-083','暗送秋波','àn sòng qiū bō','旧时比喻美女的眼睛象秋天明净的水波一样。指暗中眉目传情。','对张（作霖）则～，对曹（锟）尤密切勾结。★蔡东藩、许廑父《民国通俗演义》第一二四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-084','暗无天日','àn wú tiān rì','昏暗得看不到天上的日光。形容在反动势力统治下社会的黑暗。','上自王后，下至弄臣，骇得凝结着的神色也应声活动起来，似乎感到～的悲哀。★鲁迅《故事新编·铸剑》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-085','暗香疏影','àn xiāng shū yǐng','暗香清幽的香气；疏影稀疏的枝影。原形容梅花的香味和姿态，后被用为梅花的代称。','两个站在小桥上，疏影暗香，自甘清冷，屋后山冈积雪如银，背着手玩赏。★清·陈忱《水浒后传》第十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-086','暗中摸索','àn zhōng mō suǒ','摸索寻求，探索。在黑暗中寻找◇比喻没有人指导，独自钻研。','先生有志于木刻，是极好的事，但访木刻家是无益的，因为就是已有成绩的木刻家，也还在～。★《鲁迅书信集·致沈振黄》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-087','黯淡无光','àn dàn wú guāng','黯淡同暗淡”，不明亮，昏暗。形容失去光彩。','但是这个电报却又引起了张勋的不愉快，因为，他的十三省盟主地位因此而～。★陶菊隐《北洋军阀统治时期史话》第二十四章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-088','黯然失色','àn rán shī sè','黯然心里不舒服、情绪低落的样子；失色因惊恐而变以脸色。本指心怀不好，脸色难看◇多比喻相形之下很有差距，远远不如。','所有同类题材的绘画和它比较起来，都～。★秦牧《艺海拾贝·〈最后的晚餐〉》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-089','黯然销魂','àn rán xiāo hún','黯然心怀沮丧、面色难看的样子；销魂灵魂离开肉体。心怀沮丧得好象丢了魂似的。形容非常悲伤或愁苦。','无言独上西楼”，深闺的空寥，弥漫在漠漠的冥色里，离情别绪，～！★郭枫《且饮一杯寂寞》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-090','卬首信眉','áng shǒu shēn méi','信，通伸”。昂首伸眉。形容意气昂扬，不随波逐流。','随行逐队，则有持禄之讥；～，则有出位之戒，是亦何荣之有哉！★宋朱熹《答汪尚书书》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-091','昂首天外','áng shǒu tiān wài','抬起头望着天边。形容态度傲慢，或做事脱离实际。','某些人做事不从实际出发，往往～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-092','昂首望天','áng shǒu wàng tiān','仰起头，望着天。喻指眼光向上，作风浮泛，不肯放下架子、深入基层。','要做这件事，第一是眼睛向下，不要只是～。★毛泽东《〈农村调查〉的序言和跋》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-093','昂头挺胸','áng tóu tǐng xiōng','抬起头，挺起胸膛。形容斗志高，士气旺。参见昂首挺胸”。','你看！提到内战，就连妇人女子都反对啦……”～，老老师欣喜地叫出来。★沙汀《范老老师》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-094','昂霄耸壑','áng xiāo sǒng hè','昂高；壑峪。高出霄汉，耸立山壑。形容才能杰出，建树宏大功业。也形容志气高昂，胸怀广阔。','昔余识夫人之子稚年，固已得其～之气。★宋·陈亮《祭叶正则母夫人文》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-095','嗷嗷待哺','áo áo dài bǔ','嗷嗷哀鸣声；待等待；哺喂食。饥饿时急于求食的样子。形容受饥饿的悲惨情景。','文章尽可在别的刊物上发表，对于～的创造社的几种刊物却一字也不肯飞来。★郭沫若《学生时代·创造十年续编》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-096','聱牙佶屈','áo yá jí qū','聱牙不顺口；佶屈曲折。指文章读起来不顺口。','我今赠君亦无物，但有～村田诗。★元·戴元表《剡源集·寿陈贵白','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-097','謷牙诘屈','áo yá jié qū','同诘屈聱牙”。謷，通聱”。诘屈同佶屈”，曲折，引申为不顺畅；謷牙读起来拗口、别扭。形容文字晦涩艰深，难懂难读。','我今赠君亦无物，但有～村田诗。★元·戴元表《剡源集·寿陈贵白》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-098','鳌掷鲸吞','áo zhì jīng tūn','比喻文辞气势磅礴，跌宕起伏。亦作鳌掷鲸呿”。','至于杜之涵地负，韩之鳌掷鲸呿，尚有所未逮。★清宋荦《漫堂说诗》三','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-099','傲睨万物','ào nì wàn wù','睨斜视。斜着眼看一切事物。形容目空一切，什么都瞧不起。','……益自尊大，宝自有而～。★鲁迅《文化偏至论》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-100','傲睨一切','ào nì yī qiè','睨斜视。斜着眼看一切事物。形容目空一切，什么都瞧不起。','更有那放荡不羁，～，偏低首下心，作儿女之态。★清·魏秀仁《花月痕》第一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-101','傲睨一世','ào nì yī shì','睨斜视。高傲地旁观，对当代的一切都不看在眼里。形容傲慢自负，目空一切。','辽字睿达，幼挺拔不群，长而好学尚友，～。★《宋史·沈辽传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-102','傲睨自若','ào nì zì ruò','睨斜视；自若指满不在乎。形容自高自大、藐视一切的样子。','简雍在城下唤门。（刘）璋令开门接入。雍坐在车中，傲睨自若。★明·罗贯中《三国演义》第六十五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-103','傲雪凌霜','ào xuě líng shuāng','形容不畏霜雪严寒，外界条件越艰苦越有精神。比喻经过长期磨练，面对冷酷迫害或打击毫不示弱、无所畏惧。傲，傲慢、蔑视。','如松柏之性，～。★清·钱泳《履园丛话·谭诗·总论》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-104','傲雪欺霜','ào xuě qī shuāng','形容不畏霜雪严寒，外界条件越艰苦越有精神。比喻经过长期磨练，面对冷酷迫害或打击毫不示弱、无所畏惧。傲，傲慢、蔑视。','玉骨冰肌谁可匹，～夺第一。★元·吴昌龄《张天师》第三折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-105','八百孤寒','bā bǎi gū hán','八百形容很多；孤寒指贫寒的读书人。形容人数众多，处境贫寒的读书人。也比喻贫寒之士失去依靠。','小谪陈芳现在身，人间何事敝精神。幔亭仙客休相待，～要此人。★清·黄景仁《两当轩集·十四·岁暮怀人》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-106','八拜之交','bā bài zhī jiāo','八拜原指古代世交子弟谒见长辈的礼节；交友谊。旧时朋友结为兄弟的关系。','今日在圣贤炉前成了～，有福同享，有马同骑。★清·李绿园《歧路灯》第二十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-107','八窗玲珑','bā chuāng líng lóng','①指四壁窗户轩敞，室内通彻明亮。②比喻通达明澈的修养境界。','而今须是要打破那黑底虚静，换做个白底虚静，则～，无不融通。★《朱子语类》卷一百','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-108','八方呼应','bā fāng hū yìng','呼应彼此声气相通。泛指周围、各地。形容各方面互通声气，互相配合。','中国申办奥运的计划一提出，立即八方呼应，群情激奋。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-109','八面玲珑','bā miàn líng lóng','玲珑精巧细致，指人灵活、敏捷。本指窗户明亮轩敞◇用来形容人处世圆滑，待人接物面面俱到。','原来宝廷的为人，是～，却十分落拓。★清·曾朴《孽海花》第七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-110','八面威风','bā miàn wēi fēng','威风令人敬畏的气势。各个方面都很威风。形容神气足，声势盛。','年龄不到五十许，体态虽十分端丽，神情却八面威风。★清·曾朴《孽海花》第十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-111','八万四千','bā wàn sì qiān','本为佛教表示事物众多的数字，后用以形容极多。','～颠倒想，与君同付醉眠中。★宋·陆游《醉歌》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-112','八仙过海','bā xiān guò hǎi','相传八仙过海时不用舟船，各有一套法术。民间因有八仙过海，各显神通”的谚语◇以比喻各自拿出本领或办法，互相竞赛。','说得好，咱们就～吧！★老舍《茶馆》第一幕','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-113','八音迭奏','bā yīn dié zòu','八音古代对乐器的统称；迭交互，轮流。八类乐器轮番演奏。表示器乐齐全，演奏场面盛大。','又有谓大八音匣者，与衣厢等。触其机，～，恍如有十数人弹唱焉。★清·淮阴百一居士《壶天录》卷中','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-114','八音遏密','bā yīn è mì','遏阻止；密寂静。各种乐器停止演奏，乐声寂静。旧指皇帝死后停乐举哀◇也用以形容国家元首之死。','奉梓南归四载迟，～寄哀思。★柳亚子《中山先生奉安大典志哀》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-115','八字打开','bā zì dǎ kāi','象八”字那样，撇、捺向两边分开。原意是放着正路不走，却走歪门邪道。也形容门路很宽。','这事已～，请大家多提建议。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-116','巴巴结结','bā bā jiē jiē','①勉强，凑合。②勤恳；辛劳。③形容说话不流利。','他～地说不了几句。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-117','巴人下里','bā rén xià lǐ','①即下里巴人。古代楚国流行的民间歌曲。用以称流俗的音乐。巴，古国名，在今四川东部一带，古为楚地。下里，乡里。②泛指粗俗的。','张寅道晚生末学，‘～’之词只好涂饰闾里，怎敢陈于老太师山斗之下。”★《平山冷燕》第十七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-118','拔本塞源','bá běn sè yuán','本根本，根源。拔起树根，塞住水源。比喻防患除害要从根本上打主意。','这也是个好办法，而且简单易行，不过还不是～之计。★郭沫若《郑成功》第五章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-119','拔萃出群','bá cuì chū qún','拔超出。萃原谓草丛生的样子，引伸为聚集，指聚集在一处的人或物。超出一般，在众人之上。','曾不能～，扬芳飞文，登天庭，序彝伦，扫六合之秽。★汉·蔡邕《释诲》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-120','拔地倚天','bá dì yǐ tiān','拔突出，耸出。倚倚傍，贴近。从地面突兀而起，贴近天际。比喻高大突出，气势雄伟。','那悬崖之上，一株株苍松翠柏～，傲然屹立。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-121','拔来报往','bá lái fù wǎng','报通赴”，迅速≤快地来，很快地去。形容频繁地奔来奔去。','少顷，以足床来，置地上，促客坐；又入，携短足几至，～，蹀躞甚劳。★清·蒲松龄《聊斋志异·阿纤》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-122','拔茅连茹','bá máo lián rú','茅白茅，一种多年生的草；茹植物根部互相牵连的样子。比喻互相推荐，用一个人就连带引进许多人。','袁既病死，黎、段登台，～，弹冠相庆，徐遂入任为院秘书长。★蔡东藩、许廑父《民国通俗演义》第七十九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-123','拔苗助长','bá miáo zhù zhǎng','比喻违反事物发展的客观规律，急于求成，反而坏事。','那种不顾学生能否接受的填鸭式的教学方法，无异于～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-124','拔山盖世','bá shān gài shì','盖世超越天下人，世上第一。力能拔掉大山，形容力大勇猛，当代无比。','则～之雄，几乎其为若敖之鬼矣。★明·张岱《募造无主祠堂疏》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-125','拔山扛鼎','bá shān gāng dǐng','扛双手举起。拔起大山，举起重鼎。形容力气很大。','汉祖入关破秦而楚后之～，力大过人。★宋·邵雍《皇极经世绪言》第二卷','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-126','拔十得五','bá shí dé wǔ','拔盐，推荐。想盐十个，结果只选得五个。指盐人才不容易。','谓～而可得其半，故匿瑕含垢而求其长致。★宋陈师道《谢胡运使启》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-127','拔新领异','bá xīn lǐng yì','拔抽出；新新意；领具有；异指独特之处。指创立新意，提出独特的见解。','公风神英迈，意气倾倒，～之谈，登峰造极之理，萧然如晋、宋间人物。★宋·杨万里《石湖先生大资参政范公文集序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-128','拔宅飞升','bá zhái fēi shēng','拔拔起；宅住宅。古代传说修道的人全家同升仙界。参见拔宅上升”。','生曰得卿如此，吾何忧！顾念一人得道，～。余将远逝，一切付之于卿。”★清薄松龄《聊斋志异·白于玉》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-129','拔宅上升','bá zhái shàng shēng','拔拔起；宅住宅。古代传说修道的人全家同升仙界。','秋先，汝功行圆满，吾已申奏上帝，有旨封汝为护花使者，专管人间百花。令汝～。★明·冯梦龙《醒世恒言》卷四','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-130','跋前踬后','bá qián zhì hòu','跋踩；踬被绊倒。本指狼向前进就踩住了自己的颈肉，向后退又会被自己的尾巴绊倒。比喻进退两难。','无事之时，望影藏匿，～，日不聊生。★清·纪昀《阅微草堂笔记·滦阳续录','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-131','跋山涉水','bá shān shè shuǐ','跋山翻过山岭；涉水用脚趟着水渡过大河。翻山越岭，趟水过河。形容走远路的艰苦。','同样的青春，同样的年龄，有人～，为改变祖国一穷二白的面貌而感到莫大的幸福。★魏巍《路标》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-132','把素持斋','bǎ sù chí zhāi','把遵守。斋斋戒。指信佛者遵守吃素，坚持戒律。','人人善念看经，个个～。★明·无名氏《万国来朝》第一折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-133','罢黜百家','bā chù bǎi jiā','罢黜废弃不用。原指排除诸子杂说，专门推行儒家学说。也比喻只要一种形式，不要其他形式。','……只认朗诵词和诗。笔者却不能够赞成这～”的作风★朱自清《论朗诵诗》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-134','霸王别姬','bà wáng bié jī','姬指西楚霸王项羽的宠妾虞姬。形容英雄末路的悲壮情景。现多比喻独断专行，脱离群众，最终垮台。','不是有一出戏叫《～》吗？这些同志如果总是不改，难免有一天要别姬”就是了。★毛泽东《在扩大的中央工作会议上的讲话》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-135','白白朱朱','bái bái zhū zhū','白的白，红的红。形容不同种类、色彩各异的花木。','风风雨雨又春穷，～已眼空。★宋·杨万里《又和风雨二首》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-136','白璧青蝇','bái bì qīng yíng','白璧洁白的玉，比喻清白的人。青蝇比喻佞人。比喻善恶忠佞。','为臣子莫贵忠和孝，继美于今有凤毛，～何足较。★《群音类选》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-137','白璧三献','bái bì sān xiàn','楚人和氏得玉璞，两献楚王，两遭刖足。第三次王使治璞，得白玉，琢以为璧，世称和氏璧”。比喻不识良材或怀才不遇。','明珠暗投反按剑，～还遭刖。★明·何景明《田子行》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-138','白璧微瑕','bái bì wēi xiá','洁白的玉上有些羞点。比喻很好的人或物有些小缺点，美中不足。','智者千虑，必有一失，然而这小毛病只是～而已。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-139','白璧无瑕','bái bì wú xiá','洁白的美玉上面没有一点羞。比喻人或事物完美无缺。','虽以小姐～，何畏乎青蝇，然青蝇日集亦可憎恨耳。★明·名教中人《好俅传》第七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-140','白发丹心','bái fà dān xīn','丹心赤诚之心。形容年迈苍老，仍然怀有一颗赤诚之心。','牧羊驱马虽戎服，～尽汉臣。★唐·杜牧《河湟》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-141','白发千丈','bái fà qiān zhàng','形容头发既白且长，表示人因愁思过重而容颜衰老。','凡此诸人，今皆安往？我虽独存，～。★宋·刘克庄《后村全集·祭林寒斋文》第一百三十八卷','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-142','白圭之玷','bái guī zhī diàn','白玉圭上的一个斑点。比喻人或物大体很好，只是有些小缺点。','也不过～，并非晚节不终。★鲁迅《且介亭杂文末编·关于太炎先生二三事》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-143','白虹贯日','bái hóng guàn rì','白色的长虹穿日而过。古人认为人间有不平凡的事，就会引起这种天象的变化。实际上这不是虹而是晕，是一种大气光学现象。','且休说～，青龙藏池。★元·王实甫《丽春堂》第二折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-144','白驹过隙','bái jū guò xì','白驹白色骏马，比喻太阳；隙缝隙。象凶马在细小的缝隙前跑过一样。形容时间过得极快。','～，日月穿梭，才见梅开腊底，又早天气回阳。★明·兰陵笑笑生《金瓶梅词话》第二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-145','白龙鱼服','bái lóng yú fú','鱼服穿起鱼的外衣。白龙化为鱼在渊中游。比喻帝王或大官吏隐藏身分，改装出行。','相公～，隐姓潜名。倘或途中小辈不识高低，有毁相公者，何以处之？★明·冯梦龙《警世通言》卷四','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-146','白面书生','bái miàn shū shēng','指缺乏阅历经验的读书人。也指面孔白净的读书人。','雪儿呵，偏则把～奚落。★明·汤显祖《牡丹亭》第二十二出','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-147','白日飞升','bái rì fēi shēng','犹白日升天。道教谓人修炼得道后，白昼飞升天界成仙◇喻指一朝显贵。','左壁挂‘黄鹤楼～’，右壁悬‘洞庭湖三番渡过’。★明·兰陵笑笑生《金瓶梅词话》第三九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-148','白日见鬼','bái rì jiàn guǐ','大白天看见鬼。指工部四曹无事可做，非常清闲◇泛指事情离奇古怪或无中生有。','八戒道哥啊，我们连日造化低了。这两日～！那个化风去的老儿是谁？”★明·吴承恩《西游记》第二十一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-149','白日升天','bái rì shēng tiān','原是道教指白昼升天成为神仙◇比喻一下子富贵起来。','遂去，悉度其妻妾，于是金氏门中两代～。”★鲁迅《中国文学史略》第二十六篇','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-150','白色恐怖','bái sè kǒng bù','白惨白。指反动派残酷镇压人民的恐怖气氛。','鲁迅先生对于白色恐怖毫不畏惧，一直把密信和文稿珍藏着。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-151','白手起家','bái shǒu qǐ jiā','白手空手；起家创建家业。形容在没有基础和条件很差的情况下自力更生，艰苦创业。','你看，他发了多少财，～，靠的是谁？如今也忘了水源头了，墙上的草，两边倒着呢。★丁玲《太阳照在桑干河上》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-152','白首穷经','bái shǒu qióng jīng','直至年纪老了还在钻研经籍，犹言活到老，学到老。','兹予绩服之初，日思讲议之益，谓～之乐，尚可推以与人。★宋·苏辙《范镇可侍读太一宫使告词》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-153','白首同归','bái shǒu tóng guī','归归向、归宿。一直到头发白了，志趣依然相投。形容友谊长久，始终不渝◇用以表示都是老人而同时去世。','当君～日，是我青山独往时。★唐·白居易《九年十一月十一日感事而作》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-154','白叟黄童','bái sǒu huáng tóng','白头发的老人和黄头发的孩子。泛指老老少少。','城乡内外，红男绿女，～，联袂往观者，何止千万人！★清·壮者《扫迷帚》第九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-155','白天见鬼','bái tiān jiàn guǐ','比喻虚妄荒诞，不可能出现的事。同白日见鬼”。','周炳一面说‘我的时运太低，～！’说罢回身想走。★欧阳山《苦斗》十二','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-156','白头如新','bái tóu rú xīn','白头头发白了；新新交。指交朋友彼此不能了解，时间虽久，仍跟刚认识一样。','而八年之间，语言不接，吉凶不相问吊，反有～之嫌。★宋·陈亮《与应仲书》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-157','白头偕老','bái tóu xié lǎo','白头头发白；偕共同。夫妻相亲相爱，一直到老。','我原说过，她不会跟你～的。★巴金《寒夜》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-158','白雪阳春','bái xuě yáng chūn','原指战国时代楚国的一种较高级的歌曲。比喻高深的不通俗的文学艺术。','高山流水千年调，～万古情。★崔时佩《西厢记·琴心写恨》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-159','白衣苍狗','bái yī cāng gǒu','苍灰白色。浮云象白衣裳，顷刻又变得象苍狗。比喻事物变化不定。','正是～多翻覆，沧海桑田几变更。★明·张景《飞丸记·梨园鼓吹》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-160','白衣卿相','bái yī qīng xiàng','古时指进士。唐代人极看重进士，宰相多由进士出身，故推重进士为白衣卿相，是说虽是白衣之士，但享有卿相的资望。','小生不才杀者波，也是国家～。★元·吴昌龄《张天师》第二折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-161','白云苍狗','bái yún cāng gǒu','苍灰白色。浮云象白衣裳，顷刻又变得象苍狗。比喻事物变化不定。','真是世事～，不禁感慨系之矣！★鲁迅《华盖集后记》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-162','百般折磨','bǎi bān zhé mó','用各种方式使人在肉体上、精神上遭受痛苦。','她任凭酷刑～，紧咬着牙关，始终坚贞不屈。★《言行和心理》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-163','百弊丛生','bǎi bì cóng shēng','百形容多；弊弊端，害处。各种弊害都产生出来了。','今以十当一，是反以四钱八分铜作一钱二分用也。民间私閒改铸，～。★柯劭忞《清史稿·袁希祖传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-164','百不失一','bǎi bù shī yī','一百次中无一次失误。表示射箭或打枪命中率高，或做事有充分把握。','他把算子一动，便晓得这人姓名，穷通寿夭，～。★明·凌濛初《初刻拍案惊奇》卷七','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-165','百步穿杨','bǎi bù chuān yáng','在一百步远以外射中杨柳的叶子。形容箭法或枪法十分高明。','（关羽）带箭回寨，方知黄忠有百步穿杨之能。★明·罗贯中《三国演义》第五十三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-166','百尺竿头','bǎi chǐ gān tóu','桅杆或杂技长竿的顶端。比喻极高的官位和功名，或学问、事业有很高的成就。','功名～，自古及今，有几个干休。★元·张养浩《折桂令》曲','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-167','百川赴海','bǎi chuān fù hǎi','百表示多。川江河。所有江河都流归大海。比喻众望所归或大势所趋。也比喻许多事物由分散而汇集到一处。','许多文士在饱经战乱之苦后，如～，相继奔往邺城，归附到曹氏（曹操）周围。★《建安文学》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-168','百读不厌','bǎi dú bù yàn','厌厌烦，厌倦。读一百遍也不会感到厌烦。形容诗文或书籍写得非趁，不论读多少遍也不感到厌倦。','为什么一些作品有人～”，另一些却有人不想读第二遍呢？★朱自清《论百读不厌》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-169','百发百中','bǎi fā bǎi zhòng','形容射箭或打枪准确，每次都命中目标。也比喻做事有充分把握。','回见子牙，叩头在地丞相妙计，～。”★明·许仲琳《封神演义》第三十六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-170','百废具举','bǎi fèi jù jǔ','指许多被废置的事业都等着兴办。同百废俱举”。','其有能如水野越前、井伊直弼之鞠躬尽瘁～者乎？★梁启超《敬告当道者》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-171','百废俱举','bǎi fèi jù jǔ','指一切废置的事都兴办起来。同百废俱兴”。','‘～’的平均主义思想，以及与此相关联着的不合边区实际的‘正规化’思想，成了贯彻精简政策与集中力量于两大任务的绊脚石。★《解放日报》1942.12.23','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-172','百废俱兴','bǎi fèi jù xīng','俱全，都。许多已经荒废了的事情一下子都兴办起来。','四川屡经兵燹，廷相莅任，～，民不知扰。★《清史稿·郎廷佐传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-173','百感交集','bǎi gǎn jiāo jí','感感想；交同时发生。各种感触交织在一起。形容感触很多，心情复杂。','我是上一个世纪出生的人，能参加这样的盛会，～，思绪万千。★郭沫若《科学的春天》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-174','百花齐放','bǎi huā qí fàng','形容百花盛开，丰富多彩。比喻各种不同形式和风格的艺术自由发展。也形容艺术界的繁荣景象。','美术展览会上展出了许多新作品，～，各具风格。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-175','百喙莫辩','bǎi huì mò biàn','喙嘴，借指人的嘴。指纵有众多的嘴也不能辩解。同百口莫辩”。','素臣一段议论，如老吏断狱，使刘邦～。★清·夏敬渠《野叟曝言》第七十一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-176','百喙难辞','bǎi huì nán cí','喙嘴，借指人的嘴。指纵有众多百口也很难解释。','刘棻等已被扳入，～，遂都连坐罔上不道的罪名，谳成死罪。★蔡东藩《后汉演义》第一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-177','百家争鸣','bǎi jiā zhēng míng','指各种学术流派的自由争论互相批评。也指不同意见的争论。百家，这种观点的人或各种学术派别。鸣，发表见解。','自春秋末年以来，中国的思想得到一个极大的开放，呈现出一个～的局面。★郭沫若《吕不韦与秦王政的批判》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-178','百孔千疮','bǎi kǒng qiān chuāng','比喻毛病很多，问题严重，已经到了难以收拾的地步。','他身上的缺点虽然不少，但却不是～，不可救药。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-179','百口莫辩','bǎi kǒu mò biàn','莫不能；辩辩白。即使有一百张嘴也辩白不清。形容不管怎样辩白也说不清楚。','玉林和忠和醒悟了，一打便是祸事，若是李三顺身上有了伤，便～，官司”非输不可。★高阳《清宫外史》上册','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-180','百了千当','bǎi liǎo qiān dāng','了了结；当妥当；百、千指一切事。比喻事事妥贴，有着落。','不如屏净尘缘，竖起脊梁骨，著些精彩，究教七川八穴，～，向水边林下，长养圣胎，亦不枉受人天供养。★宋·释惟白《续传灯录》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-181','百里挑一','bǎi lǐ tiāo yī','一百个当中就挑出这一个来。形容人才出众。','对报名参军的人挑选很严格，可以说是～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-182','百炼成刚','bǎi liàn chéng gāng','刚通钢。铁经过反复锤炼便成为坚韧的钢。比喻人经过多次磨炼而成为有用之才。','有人身经百战，～，炉火纯青，喜于心而不形于色。★徐迟《火中凤凰·凤翔》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-183','百年大计','bǎi nián dà jì','大计长远的重要的计划。指关系到长远利益的计划或措施。','～，教育为本。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-184','百年树人','bǎi nián shù rén','树种植，栽培。比喻培养人才是长期而艰巨的事。','古人都知道～的道理，我们更应该把培养人才这件大事抓好。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-185','百鸟朝凤','bǎi niǎo cháo fèng','朝朝见；凤凤凰，古代传说中的鸟王。旧时喻指君主圣明而天下依附，后也比喻德高望重者众望所归。','那些玉斝中的长春露酒也都由站在身边侍候的宫女接过去倾入一只绘着～的大瓷缸中。★姚雪垠《李自成》第二卷第三十一章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-186','百身何赎','bǎi shēn hé shú','百身自身死一百次；赎抵。拿一百个我，也无法把你换回来了。表示极沉痛地悼念。','一见无期，～。★南朝·梁·刘令娴《祭夫徐敬业文》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-187','百身莫赎','bǎi shēn mò shú','百身自身死一百次；赎抵。拿一百个我，也无法把你换回来了。表示极沉痛地悼念。','旷官之罪，职～矣。★明·袁宏道《去吴七牍·乞改稿一》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-188','百世之师','bǎi shì zhī shī','世世代代的老师，指才德高尚而永远可为人师表的人。','卓为～；杰作雄辞，散落四夷之远。★宋·陆游《贺薛安抚兼制置启》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-189','百兽率舞','bǎi shòu shuài wǔ','各种野兽，相率起舞。旧指帝王修德，时代清平。','大礼告成，伺候各官，循例三呼，国乐以外，杂以军乐，仿佛有凤凰来仪，～景象。★蔡东藩、许廑父《民国通俗演义》第三四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-190','百岁千秋','bǎi suì qiān qiū','一百年，一千载。形容岁月漫长，历时很久。','明·康海《王兰卿》第三折便活到百岁千秋索一死，则不如另寻个身计。”','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-191','百无禁忌','bǎi wú jìn jì','百所有的，不论什么；禁忌忌讳。什么都不忌讳。','则知太公封神，古有此说。今人于门户每书姜太公在此，～，亦非无所本矣。★鲁迅《小说旧闻钞·封神传衍义》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-192','百无聊赖','bǎi wú liáo lài','聊赖依赖。精神上无所寄托，感到什么都没意思。','在～中，随手抓过一本书来，科学也好，文学也好，横竖什么都一样。★鲁迅《彷徨·伤逝》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-193','百无是处','bǎi wú shì chù','犹言一无是处。形容全都是错的，没有一点对的地方。','每日价茶不茶，饭不饭，～。★元·王氏《粉蝶儿·寄情人》套曲','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-194','百无一是','bǎi wú yī shì','干一百件事，也没有做对一件。形容全都做错了，一无是处。','此人做事百无一是，如若重用应当三思而后行。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-195','百依百从','bǎi yī bǎi cóng','百比喻很多；依顺从；从跟从。什么都依从。形容一味顺从。','对孩子～是不行的。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-196','百依百顺','bǎi yī bǎi shùn','依、顺顺从。什么都依从。形容一切都顺从别人。','这安公子是那女孩儿一般～的人。★清·文康《儿女英雄传》第三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-197','百战不殆','bǎi zhàn bù dài','经历许多次战役，都没有遭到危险。形容善于用兵。','自古名将料敌制胜，训练士兵，故可使赴汤蹈火，～。★《金史·刘炳传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-198','百折不回','bǎi zhé bù huí','折挫折。比喻意志坚强，无论受到多少次挫折，毫不动摇退缩。','耿耿自始，～。★清·姚莹《复杨君论诗文书》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-199','百折不挠','bǎi zhé bù náo','折挫折；挠弯曲。比喻意志坚强，无论受到多少次挫折，毫不动摇退缩。','汉阳民军总司令黄兴，系湖南长沙县人，向来主张革命，屡仆屡起，～。★蔡东藩、许廑父《民国通俗演义》第三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-200','百折不屈','bǎi zhé bù qū','受到无数挫折都不屈服、动摇。形容意志坚强。','要像总理那样……奋不顾身，～。★郭小川《痛悼敬爱的周总理》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-201','败不旋踵','bài bù xuán zhǒng','形容很快就遭到失败。旋踵，转动一下脚后跟。','未议致身，先图问鼎，假称伊霍之事，将肆莽卓之心，人神同疾，～。★《北史·杨敷传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-202','稗官野史','bài guān yě shǐ','稗官古代的一种小官，专给帝王搜集街谈巷语，道听途说，以供省览，后称小说或小说家为稗官。指旧时的小说和私人编撰的史书。','如今我要将这碑记付给文人墨士，做为～，流传海内。★清·李汝珍《镜花缘》第七十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-203','班班可考','bān bān kě kǎo','班班明显的样子。指事情源流始末清清楚楚，可以考证。','亦尝有此言，明载简册，～。★清·钱彩《说岳全传》第七十三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-204','班荆道故','bān jīng dào gù','班铺开；道叙说。用荆铺在地上坐在上面谈说过去的事情。形容老朋友在路上碰到了，坐下来谈谈别后的情况。','一次邂逅相逢，一次～，竟使一位艺术殉道者在冥冥里忽闻天籁，于混沌中顿悟禅机。”★李存葆《伏虎草堂主人》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-205','班荆道旧','bān jīng dào jiù','指朋友相遇于途，铺荆坐地，共叙情怀◇泛指朋友相遇，共叙离情。亦作班荆道故”。','鲍叔、管仲，分财无猜；归生、伍举，～。★晋·陶潜《与子俨等疏》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-206','班马文章','bān mǎ wén zhāng','汉代史学家司马迁与班固的并称。泛指可与班固、司马迁相比美的文章。','～由夙慧，庾鲍诗句实前缘。★清·刘璋《飞花艳想》第二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-207','班门弄斧','bān mén nòng fǔ','在鲁班门前舞弄斧子。比喻在行家面前卖弄本领，不自量力。','闻得亭亭姐姐学问渊博，妹子何敢～，同他乱谈。★清·李汝珍《镜花缘》第五十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-208','班师回朝','bān shī huí cháo','班调回。调动出征的军队返回首都，指出征的军队胜利返回朝廷。','后主（刘禅）下诏，宣孔明班师回朝。★明·罗贯中《三国演义》第一百回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-209','班衣戏彩','bān yī xì cǎi','指身穿彩衣，作婴兒戏耍以娱父母◇以之为老养父母的孝亲典故。','虽无儿，效老莱，～。★清·新广东武生《黄萧养回头》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-210','斑驳陆离','bān bó lù lí','斑驳色彩杂乱；陆离参差不一。形容色彩纷杂。','铜器一，器大可合抱，重数十斤，侧有双环，不知何用，～，瓶亦古。★清·蒲松龄《聊斋志异·古瓶》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-211','斑衣戏彩','bān yī xì cǎi','指身穿彩衣，作婴兒戏耍以娱父母◇以之为老养父母的孝亲典故。','那二十四孝上～，他们不能来戏彩引老祖宗笑一笑，我这里好容易引的老祖宗笑一笑……难道反笑我不成？★《红楼梦》第五四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-212','搬弄是非','bān nòng shì fēi','搬弄挑拔。把别人的话传来传去，有意挑拔，或在背后乱加议论，引起纠纷。','况三姑六婆，里外搬弄是非，何能不生事端。★清·李汝珍《镜花缘》第十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-213','板上钉钉','bǎn shàng dìng dīng','在石板上钉上铁钉。比喻事情已经决定，不能改变。','海云是已经定性、已经作了～的正式结论的阶级敌人。★王蒙《蝴蝶》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-214','版筑饭牛','bǎn zhù fàn niú','版筑，造土墙；饭牛，喂牛◇以之为贤臣出身微贱之典。','古今相望，落落然如骑星辰，与夫起～者异矣。★唐·刘禹锡《唐故中书侍郎平章事韦公集纪》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-215','半壁江山','bàn bì jiāng shān','半壁半边；江山比喻国家疆土。指在敌人入侵后残存或丧失的部分国土。','军声壮，阵法多，～全仗我。★清·吴梅《风洞山·阅兵》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-216','半部论语','bàn bù lún yǔ','旧时对儒学经典之一《论语》的夸赞之辞，掌握半部《论语》，人的能力就会提高，就能治理国家。','况且从前古人以～治天下，就是半部亦何妨。★清·李宝嘉《官场现形记》第六十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-217','半筹不纳','bàn chóu bù nà','筹古代计算工具，引伸为计策；纳缴纳。半条计策也拿不出来。比喻一点办法也没有。','万骑交驰，两军相见，咱手里～。★元·朱凯《昊天塔》第二折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-218','半筹莫展','bàn chóu mò chǎn','半条计策也拿不出来。比喻一点办法也没有。','惟自民国成立之日，则予三主张建设反致～，一败涂地。★孙中山《建国方略自序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-219','半间半界','bàn gān bàn gà','①不彻底，不深透。②不明确。③犹言不上不下。④谓平庸。','丘宗卿亦受群儿谤伤之言，～，州府卒归狱于赵穿，亮以此身既存而不复问矣。★宋·陈亮《又乙巳春书》之一','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-220','半截入土','bàn jié rù tǔ','截段。半段身子埋入土内。比喻人在世不久了。','差多了，差多了！人到三十五，就半截入土了。★老舍《谁先到了重庆》第一幕','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-221','半斤八两','bàn jīn bā liǎng','八两即半斤。一个半斤，一个八两。比喻彼此一样，不相上下。','众将看他两个本事，都是～的，打扮也差不多。★明·施耐庵《水浒全传》第一百七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-222','半路出家','bàn lù chū jiā','原指成年后才出家做和尚或尼姑。比喻中途改行，从事另一工作。','他不理会内行的嗤笑，写啊改啊，改啊写啊，终于写出了好作品，成了一个颇有希望的～的作家。★公今度《长短录》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-223','半路修行','bàn lù xiū xíng','原指成年后才出家做和尚或尼姑。比喻中途改行，从事另一工作。','茅鹿门先生，文章擅海内……晚喜作诗，自称～，语多率易。★明·朱国祯《晚幢小品·俚诗有本》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-224','半身不遂','bàn shēn bù suí','遂通随”，顺从。原为医学病症名，指半边身体不能随意转动。有时比喻诗文部分好，部分不好，不够匀称。','蒋百里在宜山的南边路上，汽车坏了，他受了一下子凉，就有一点～的样子。★冯玉祥《我所认识的蒋介石》第三十一章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-225','半生不熟','bàn shēng bù shú','没有完全成熟或未烹煮至可食用的程度。比喻不熟悉；不熟练。','五个中间的老徐能说几句～的广府话。★茅盾《过封锁线》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-226','半死半生','bàn sǐ bàn shēng','①未全死。②比喻无意义、无生气的苟且的生活。','惟独～的苟活，是全盘失错的。因为他挂了生活的招牌，其实却引人到死路上去！”★鲁迅《华盖集·北京通信》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-227','半死不活','bàn sǐ bù huó','指没有生机和活力。死又死不了，活着又受罪。','想跑，水裹住他的脚，他就那么～的，低着头一步一步的往前曳。★老舍《骆驼祥子》十八','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-228','半途而废','bàn tú ér fèi','废停止。指做事不能坚持到底，中途停顿，有始无终。','如果就此请假回国，这里的事～，将来保举弄不到，白吃一趟辛苦。★清·李宝嘉《官场现形记》第五十六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-229','半推半就','bàn tuī bàn jiù','推抵拒，推托；就靠拢，迎上去。一面推辞，一面靠拢上去。形容装腔作势假意推辞的样子。','与其学那俗态，～，耽搁工夫；据俺主意，不如从实收了，倒也爽快。★清·李汝珍《镜花缘》第三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-230','半信半疑','bàn xìn bàn yí','有点相信，又有点怀疑。表示对真假是非不能肯定。','众人听了，也都～。★清·曹雪芹《红楼梦》第九十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-231','半夜三更','bàn yè sān gēng','一夜分为五更，三更是午夜十二时。指深夜。','他常常工作到～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-232','半疑半信','bàn yí bàn xìn','有点怀疑，又有点相信。表示对真假是非不能肯定。','若他人听过了，～，若存若亡，安得不惰。★《朱子全书》卷十六','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-233','蚌鹬相持','bàng yù xiāng chí','比喻双方相争，两败俱伤，徒使第三者得利。','天方厌羌，内难屡起，权臣擅事，～。★宋·秦观《边防中》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-234','傍人门户','bàng rén mén hù','傍依靠，依附；门户门第。比喻依赖别人，不能自立。','虽说咱们穷，究竟比他～好多着呢。★清·曹雪芹《红楼梦》第一０九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-235','傍若无人','páng ruò wú rén','好象旁边没有人在。形容神情态度高傲自如。','陈太尉初下船时，昂昂然～，坐在中间。★明·施耐庵《水浒传》第七十五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-236','棒打鸳鸯','bàng dǎ yuān yāng','用木棒打散一双鸳鸯。比喻拆散恩爱的夫妻或情侣。','啼痕界破残妆面，德言分镜几时圆？远水高山，眼睁睁～散。★明·李开先《宝剑记》第十九出','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-237','包办代替','bāo bàn dài tì','指应该和有关的人一起商量或一起做的事，却独自办理，不让旁人参与。','我们工作同志作好参谋，不要指手划脚，～。★陈残云《山谷风烟》第三四章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-238','包藏祸心','bāo cáng huò xīn','包藏隐藏，包含；祸心害人之心。心里怀着害人的恶意。','初与我为客侣，不意～，隐我血赀，悍不还，今愿得而甘心，何父之有？★清·蒲松龄《聊斋志异·柳氏子》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-239','包罗万象','bāo luó wàn xiàng','包罗包括；万象宇宙间的一切景象，指各种事物。形容内容丰富，应有尽有。','你怎言～，迟早飞升。★明·许仲琳《封神演义》第十三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-240','褒贬与夺','bǎo biǎn yǔ duó','与夺给予或夺取。指对人或事物给予赞扬或批评。','若使修著一代之典，～，诚一时之俊也。★《晋书·祖逖传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-241','褒善贬恶','bāo shàn biǎn è','褒赞扬；贬批评。对好人好事加以赞扬；对坏人坏事加以斥责。指分清善恶，提出公正的评价。','其中～，尊君抑经，内夏外夷，正名谨分，也不是等闲的文字也。★明·桑绍良《独乐园》第一折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-242','褒衣博带','bāo yī bó dài','褒、博形容宽大。着宽袍，系阔带。指古代儒生的装束。','～进贤冠，礼乐东方万国看。★清·黄遵宪《续怀人》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-243','薄寒中人','bó hán zhòng rén','薄寒轻微的寒气。中人伤人。指轻微的寒气也能伤害人的身体。也比喻人在衰老或患难之中时经不住轻微的打击。','～老可畏，热酒浇肠气先压。★宋·苏轼《九月黄楼作》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-244','宝山空回','bǎo shān kōng huí','走进到处是宝物的山里，却空手出来。比喻根据条件，本来应该有丰富的收获，却一无所得（多指求知）。','海外有两句口号道刘好若临歧舌不知韵，如入宝山空手回。”★清·李汝珍《镜花缘》第二十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-245','饱经风霜','bǎo jīng fēng shuāng','饱充分；经经历；风霜比喻艰难困苦。形容经历过长期的艰难困苦的生活和斗争。','人们那被晒黑的～的脸上，显出严肃而紧张的神情。★冯德英《苦菜花》第一章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-246','饱食暖衣','bǎo shí nuǎn yī','饱食吃得饱；暖衣穿得暖。形容生活宽裕，衣食丰足。','今为若计，欲舞文乱法，快意一时，而身陷刑戮乎？欲守公奉法，～，与妻子处乎？★清·王晫《今世说·政事》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-247','饱食终日','bǎo shí zhōng rì','终日整天。整天吃饱饭，不动脑筋，不干什么正经事。','人如果～，无所用心，那是最没有出息的。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-248','保残守缺','bǎo cán shǒu quē','①指汉代今文经学派儒生墨守残缺不全的今文经典而拘执一家之言◇常用以比喻泥古守旧，不知改进。②指保藏残缺的古籍文献。','两汉而下，维多～之人，六经所传，未有继往开来之哲。★清·顾炎武《华阴县朱子祠堂上梁文》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-249','报李投桃','bào lǐ tóu táo','意思是他送给我桃儿，我以李子回赠他。比喻友好往来或互相赠送东西。','只指望～，那顾他祀佛看经。★明·高濂《玉簪记·诳告》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-250','抱布贸丝','bào bù mào sī','布古代一种货币；贸买卖。带了钱，来买丝。借指和女子接近。亦指进行商品交易。','今羞无语自沉吟，咫尺相思万里心。～君亦误，知音尽付七弦琴。★明·洪榝《清平山堂话本·风月瑞仙亭》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-251','抱残守缺','bào cán shǒu quē','抱着残缺陈旧的东西不放。形容思想保守，不求改进。','这些似乎都是～，汇集众说而成。★朱自清《经典常谈·周易第二》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-252','抱残守阙','bào cán shǒu quē','①守着残缺的东西不放。形容思想保守，不接受新事物。②谓笃守古学古道。③喻在条件很差的情况下坚持着做。','在新产品、新设备、新工艺、新材料竞相涌现的今天，任何一个企业，如果～，不注意品种质量，将会走投无路。★《人民日报》1981.4.2','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-253','抱成一团','bào chéng yī tuán','保持一致，行动起来像一个人。形容关系极为亲密。','他们相互～，结党营私。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-254','抱打不平','bào dǎ bù píng','遇见不公平的事，挺身而出，帮助受欺负的一方。','不瞒两位说，老汉平生，最喜欢劫副教授济贫抑强扶弱～。★清·曾朴《孽海花》第三十五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-255','抱负不凡','bào fù bù fán','抱负远大的志向。指有远大的志向，不同一般。','雨村兄真～也。★清·曹雪芹《红楼梦》第一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-256','抱关击柝','bào guān jī tuò','柝木梆；抱关守关；击柝打更巡夜。守关巡夜的人。比喻职位卑下。','宜乎辞尊而居卑，辞富而居贫，若～者可也。★唐·韩愈《争臣论》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-257','抱恨终天','bào hèn zhōng tiān','恨悔恨；终天终身。旧指因父母去世而一辈子感到悲痛。现指因做错某事而后悔一辈子。','今老母已丧，～，身虽在彼，誓不为设一谋。★明·罗贯中《三国演义》第四十一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-258','抱火厝薪','bào huǒ cuò xīn','厝同措”，置放。薪柴火。把火放在柴草底下。比喻危机即将出现。','汉文之世，九州晏然，贾谊独以为如抱火厝于积薪之下而寝其上。★《资治通鉴·世祖武皇帝泰始三年》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-259','抱火卧薪','bào huǒ wò xīn','比喻处境险恶，而不自知。或指险事即将出现。','谊之所欲痛哭，比今为缓；～之喻，于今而急。★《三国志·吴志·华覈传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-260','抱头鼠窜','bào tóu shǔ cuàn','抱着头，象老鼠那样惊慌逃跑。形容受到打击后狼狈逃跑。','吓得这些人一个个～而逃。★清·李宝嘉《文明小史》第九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-261','豹死留皮','bào sǐ liú pí','豹子死了，皮留在世间。比喻将好名声留传于后世。','则其人肉体虽死，精神永生。俗语说‘人死留名，～’，也就是这个意思。★冯玉祥《我的生活》第三十八章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-262','鲍鱼之肆','bào yú zhī sì','鲍咸鱼；肆店铺。卖咸鱼的店。比喻坏人成堆的地方。','智者见智，仁者见仁，入～，而不自知其臭，其斯之谓乎？★清·忧患余生《〈官场现形记〉序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-263','暴风骤雨','bào fēng zhòu yǔ','暴、骤急速，突然。又猛又急的大风雨。比喻声势浩大，发展急速而猛烈。','有雌雄二鸟，原在一处同飞，忽被～惊散。★明·吴承恩《西游记》第六十九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-264','暴虎冯河','bào hǔ píng hé','暴虎空手搏虎；冯河涉水过河。比喻有勇无谋，鲁莽冒险。','俺张孔目怎还肯缘木求鱼，鲁斋郎他可敢～？★元·关汉卿《鲁斋郎》第四折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-265','暴戾恣睢','bào lì zì suī','暴戾凶恶、残暴；恣睢任意做坏事。形容凶残横暴，想怎么干就怎么干。','这位新官，或是慈祥恺恻，叫人感恩；或是暴戾瓷睢，叫人畏惧，做书的人，都不暇细表。★清·李宝嘉《文明小史》第十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-266','暴腮龙门','pù sāi lóng mén','象鱼仰望龙门而不得上一样。科举时代比喻应进士试不第，后也比喻生活遭遇挫折，处境窘迫。','江海大鱼集门下，不得上；上即为龙。故云‘～，垂耳辕下。’★明·李贽《初潭集·师友六》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-267','暴殄天物','bào tiǎn tiān wù','暴损害，糟蹋；殄灭绝；天物指自然生物。原指残害灭绝天生万物◇指任意糟蹋东西，不知爱惜。','既有许多值钱有东西，任人作践了，也似乎～。★清·曹雪芹《红楼梦》第五十六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-268','暴跳如雷','bào tiào rú léi','暴暴烈，急躁。急怒叫跳，象打雷一样猛烈。形容又急又怒，大发脾气的样子。','他哥哥知道了，气得～。叫了他去骂。★清·吴趼人《二十年目睹之怪现状》第二十三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-269','暴衣露盖','pù yī lù gài','日晒衣裳，露湿车盖。形容奔波劳碌。暴，晒。','陛下～，栉风沐雨，曾不顾惜此。★明·杨慎《丁丑封事》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-270','暴衣露冠','pù yī lù guàn','日晒衣裳，露湿冠冕。形容奔波劳碌。暴，晒。','足下甚苦，～，将兵助楚讨不义，足不何不自喜也？臣原以事见，而曰‘吾方以天下为事，未暇见儒人也’。★《史记·郦生陆贾列传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-271','暴躁如雷','bào zào rú léi','暴暴烈，急躁。急怒叫跳，象打雷一样猛烈。形容又急又怒，大发脾气的样子。','严贡生越发恼得～。★清·吴敬梓《儒林外史》第六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-272','卑辞重币','bēi cí zhòng bì','卑谦恭；重厚；币礼物。说谦虚的话，送厚重的礼。形容对人有所求。','君诚不惜～，以求诸侯于楚，楚必许之。★明·冯梦龙《东周列国志》第三十三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-273','卑宫菲食','bēi gōng fěi shí','指宫室简陋，饮食菲薄。旧时用以称美朝廷自奉节俭的功德。','～，以丰功臣之赏；披怀虚己，以纳谟士之算。★晋·陆机《辩亡论下》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-274','卑躬屈节','bēi gōng qū jié','卑躬低头弯腰；屈节屈辱节操。形容没有骨气，低声下气地讨好奉承。','小兔子～，拿了愚表弟萧慎的名片。★清·李宝嘉《官场现形记》第四十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-275','卑躬屈膝','bēi gōng qū xī','卑躬低头弯腰；屈膝下跪。形容没有骨气，低声下气地讨好奉承。','不管有多大困难也不能向朝廷～，用变节投降的办法，苟安一时。★姚雪垠《李自成》第一卷第十四章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-276','卑礼厚币','bēi lǐ hòu bì','卑礼谦恭的礼节；厚币厚重的币帛。比喻聘请人员的郑重殷切。','朝廷～来延聘他，他在宋朝有多大的前程，要装模作样，高蹈远引，这便是不中抬举了。★清·吴趼人《痛史》第二十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-277','杯弓蛇影','bēi gōng shé yǐng','将映在酒杯里的弓影误认为蛇。比喻因疑神疑鬼而引起恐惧。','金玦厖凉含隐痛，～负奇冤。★清·黄遵宪《感事》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-278','杯盘狼藉','bēi pán láng jí','狼藉象狼窝里的草那样散乱。杯子盘子乱七八糟地放着。形容吃喝以后桌面杂乱的样子。','这桌子微醺，那桌子半酣，～，言语喧哗。★清·李绿园《歧路灯》第八十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-279','杯盘狼籍','bēi pán láng jí','杯盘等放得乱七八糟。形容宴饮已毕或将毕时的情景。','[美娘]醉眼朦胧，看见房中灯烛辉煌，～。★《醒世恒言·卖油郎独占花魁》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-280','杯水车薪','bēi shuǐ chē xīn','用一杯水去救一车着了火的柴草。比喻力量太小，解决不了问题。','有新债未动毫分的，除了承许夏鼎三十两外，大有～之状。★清·李绿园《歧路灯》第七十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-281','杯中蛇影','bēi zhōng shé yǐng','比喻因疑神疑鬼而引起恐惧。同杯弓蛇影”。','～，《世说》以为乐广事，《风俗通》以为主簿杜宣事。★清·袁枚《随园随笔·古书所载不同》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-282','悲不自胜','bēi bù zì shèng','胜能承受。悲伤得自己不能承受。形容极度悲伤。','是年冬初，丽人无故，忽潸然泪下，～，怪而问之，初则隐忍弗言，继则举声大恸。★明·李昌祺《剪灯余话·秋夕访琵琶亭记》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-283','悲欢离合','bēi huān lí hé','悲伤、欢乐、离散、聚会。泛指生活中经历的各种境遇和由此产生的各种心情。','童年的记忆最单纯最真切，影响最深最久，种种～，回想起来最有意思。★朱自清《我是扬州人》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-284','悲天悯人','bēi tiān mǐn rén','悲天哀叹时世；悯人怜惜众人。指哀叹时世的艰难，怜惜人们的痛苦。','君生平绝口弗谈政治，独其～之怀，流露于不自觉，有如此者。★柳亚子《燕子龛遗诗序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-285','北门锁钥','běi mén suǒ yuè','原指北城门上的锁和钥匙◇借指北方的军事要地。','宋·朱熹《五朝名臣言行录》皇上以朝廷无事，北门锁钥，非准不可。”','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-286','北辕适楚','běi yuán shì chǔ','北辕车子向北行驶；适到。楚在南方，赶着车往南走。比喻行动与目的相反。','欲望凤来百兽舞，何异北辕将适楚。★唐·白居易《新乐府·立部伎》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-287','北辙南辕','běi zhé nán yuán','①想往南却驾车向北行驶。比喻行为和目的相反。②车子北往南来。喻人行无定迹。','数十年以来，～，风樯篷底，有所见即借钞，或录草稿以归。★清·陆以湉《冷庐杂识·徐敬斋明经》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-288','背碑覆局','bèi bēi fù jú','看过的碑文能背诵，棋局乱后能复旧。指记忆力强。','智周聪慧，举朝无比，日诵数万言，能～。★《太平广记》卷一四七引唐·韩琬《御史台记·高智周》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-289','背城借一','bèi chéng jiè yī','背背向；借凭借；一一战。在自己城下和敌人决一死战。多指决定存亡的最后一战。','合家细弱，依栖于此，屡被封家女子，横见摧残，今欲～，烦君属檄草耳。★清·蒲松龄《聊斋志异·绛妃》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-290','背城一战','bèi chéng yī zhàn','背背向。在自己城下和敌人决一死战。多指决定存亡的最后一战。','他皱着眉头问道可是我们怎么～呢？”★茅盾《子夜》十八','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-291','背道而驰','bèi dào ér chí','背背向；道道路；驰奔跑。朝相反的方向跑去。比喻彼此的方向和目的完全相反。','道学先生于是乎从而禁之，虽然很象～，其实倒是心心相印。★鲁迅《坟·从胡须说到牙齿》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-292','背井离乡','bèi jǐng lí xiāng','背离开；井古制八家为井，引伸为乡里，家宅。离开家乡到外地。','～，卧雪眠霜。★元·马致远《汉宫秋》第三折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-293','背水一战','bèi shuǐ yī zhàn','背水背向水，表示没有退路。比喻与敌人决一死战。','挫折也有两重性。它可以把人置于死地，也可能使人置于死地而后生。他只有～了。★理由《高山与平原》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-294','背信弃义','bèi xìn qì yì','背违背；信信用；弃扔掉；义道义。违背诺言，不讲道义。','～是插在我背上的一把尖刀。★曹禺《王昭君》第五幕','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-295','倍道兼行','bèi dào jiān xíng','倍、兼加倍；道指行程。每天加倍行进，一天走两天的路程。形容加速急行。','～，召三方兵，大会于陈许之郊。★《晋书·景帝纪》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-296','悖入悖出','bèi rù bèi chū','悖违背、胡乱。用不正当的手段得来的财物，也会被别人用不正当的手段拿去→乱弄来的钱又胡乱花掉。','诉者多矣。神以为～，自作之愆；杀人人杀，相酬之道，置不为理也。★清·纪昀《阅微草堂笔记·槐西杂志四》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-297','被发文身','pī fà wén shēn','被发散发；文身身上刺花纹。原指古代吴越一代的风俗◇也用以泛指未开化地带的风俗。','禹入裸国，～，墨子入楚，锦衣吹笙，非乐而为此也。★章炳麟《驳康有为论革命书》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-298','被发缨冠','pī fà yīng guàn','来不及将头发束好，来不及将帽带系上。形容急于去救助别人。','此种举动，岂英之前人曾受黑番何项德泽，不然，何～如此耶？★严复《救亡决论》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-299','被发左衽','pī fà zuǒ rèn','被发散发不作髻；左衽瓣襟向左掩。指古代中原地区以外少数民族的装束。也指沦为夷狄。','或～，奋迅泥滓。★晋·潘岳《西征赋》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-300','被褐怀玉','pī hè huái yù','身穿粗布衣服而怀抱美玉。比喻虽是贫寒出身，但有真才实学。','今天下得无有～而钓于渭滨者乎？★三国魏·曹操《求贤令》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-301','被褐怀珠','pī hè huái zhū','身穿粗布衣服而怀抱宝珠。比喻虽是贫寒出身，但有真才实学。','他则是假躯劳幻世愚眸，～，含素藏脩。★明·朱权《冲漠子》第四折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-302','被坚执锐','pī jiān zhí ruì','穿坚固甲胄，握锐利武器。谓上阵战斗或作好战斗准备。','其将帅首鼠两端，唯利是视，孰能～，长驱深入，系马埋轮，奋不顾命，以先士卒者乎！★宋·司马光《资治通鉴》卷第一百六十九','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-303','奔轶绝尘','bēn yì jué chén','形容跑得极快，迅速前进。绝尘，脚不沾尘土。','章太炎却自崖而返”，退居于宁静的学者，鲁迅则～，自此远矣”。★宋云彬《因纪念鲁迅而想到章太炎》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-304','奔走呼号','bēn zǒu hū háo','奔走奔跑◆号叫喊。一面奔跑，一面呼唤。形容处于困境而求援。','勇敢的国民，一经览到二十一条件，群以为亡国惨兆，就在目前，于是～，力图挽救。★蔡东藩、许廑父《民国通俗演义》第四十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-305','本来面目','běn lái miàn mù','原为佛家语，指人的本性◇多比喻事物原来的模样。','这一润色，留传固然留传了，但可惜的是一定失去了许多～。★鲁迅《且介亭杂文·门外文谈》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-306','本末倒置','běn mò dào zhì','本树根；末树梢；置放。比喻把主次、轻重的位置弄颠倒了。','该简者你却详而不简，该详者你又简而不详。～，批评你还不愿意？乱弹琴！★曲波《林海雪原》一二','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-307','笨鸟先飞','bèn niǎo xiān fēi','行动笨拙的鸟要先飞。比喻能力差的人怕落后，做事比别人先动手。','女儿刻苦、自觉、用功，全靠～保持了各门功课全班第一。★毕飞宇《九层电梯》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-308','绷扒吊拷','bēng bā diào kǎo','古代的一种刑罚。强行脱去衣服，捆绑并吊起来拷打。绷捆绑。扒脱掉。','他把～般般用，情节根由细细穷，那其间枯皮朽骨难禁痛，少不得从实攀供。★元·纪君祥《赵氏孤儿》第二折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-309','逼上梁山','bī shàng liáng shān','比喻被迫起来反抗。现也比喻被迫采取某种行动。','可以说差不多的人都是～的。★姚雪垠《李自成》第一卷第二十八章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-310','鼻青眼肿','bí qīng yǎn zhǒng','鼻子发青，眼睛肿起。形容脸部伤势严重。亦比喻遭受严重打击、挫折的狼狈相。','现在蒋介石在其他各战场，碰得～。★杜鹏程《保卫延安》第二章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-311','匕鬯不惊','bǐ chàng bù jīng','匕古代的一种勺子；鬯香酒；匕和鬯都是古代宗庙祭祀用物。形容军纪严明，所到之处，百姓安居，宗庙祭祀，照常进行。','赣、宁之乱，坐镇上游，～，指挥若定。★蔡东藩、许廑父《民国通俗演义》第三十六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-312','比比皆是','bǐ bǐ jiē shì','比比一个挨一个。到处都是，形容极其常见。','上自朝廷，下至草野，～。★清·曹雪芹《红楼梦》第二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-313','比户可封','bǐ hù kě fēng','差不多每家每户都有可受封爵的德行。用以泛指风俗淳美。','夫古之所谓至治极盛者，曰‘家给人足’，曰‘～’，曰‘刑措不用’。★严复《原强》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-314','比肩而立','bǐ jiān ér lì','比肩并肩。肩并肩地站立。比喻彼此距离极近。','虽使间世而生，何异～！★宋·陈亮《贺周丞相启》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-315','比肩继踵','bǐ jiān jì zhǒng','比挨着；踵脚跟。肩挨着肩，脚跟着脚。形容人很多，很拥挤。','大街上，行人～，十分热闹。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-316','比权量力','bǐ quán liàng lì','比较衡量两方面的权力和力量。也用来指衡量两方面的轻重。','设我中国至此时而不一变，安能埒于欧洲诸大国，而与之～也哉！清·王韬《变法中》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-317','比屋而封','bǐ wū ér fēng','指上古之世教化遍及四海，家家都有德行，堪受旌表◇泛称风俗淳美。','臣推此以广其义，舜弹五弦之琴，咏《南风》之诗，而天下自理，由尧人可～也。★《晋书·段灼传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-318','比屋可封','bǐ wū kě fēng','意思是在唐、虞时代，贤人很多，差不多每家都有可受封爵的德行◇比喻社会安定，民俗淳朴。也形容教育感化的成就。','夫古之所谓至治极盛者，曰家给人足，曰～。★清·严复《原强》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-319','比翼连枝','bǐ yì lián zhī','比翼鸟名。传说此鸟一目一翼，须两两齐飞。比喻夫妇亲密不离。','但愿你百岁夫妻长好，比翼共连枝，无异般。★明·谢谠《四喜记·大宋毕姻》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-320','比翼齐飞','bǐ yì qí fēi','比翼翅膀挨着翅膀。齐飞成双的并飞。比喻夫妻情投意合，在事业上并肩前进。','居里夫妇在科学征途上～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-321','比翼双飞','bǐ yì shuāng fēi','比翼翅膀挨着翅膀。双飞成双的并飞。比喻夫妻情投意合，在事业上并肩前进。','不是妾身多薄幸，只因司马太风骚，效神凤，下丹霄，～上泬寥。★明·朱权《卓文君》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-322','彼此彼此','bǐ cǐ bǐ cǐ','常用做客套话，表示大家一样。亦指两者比较差不多。','大家彼此彼此，没有什么区别。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-323','彼竭我盈','bǐ jié wǒ yíng','彼他，对方；竭尽；盈充满。他们的勇气已丧失，我们的士气正旺盛。','文中……叙述了利于开始反功的时机——～之时。★毛泽东《中国革命战争的战略问题》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-324','笔伐口诛','bǐ fá kǒu zhū','伐声讨，攻打；诛痛斥，责罚。从口头和书面上对坏人坏事进行揭露和声讨。','而吾辈不畏强御，不避斧钺，～，大声疾呼。★清·忧患余生《官场现形记序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-325','笔墨官司','bǐ mò guān sī','笔墨指文字或文章。比喻用文字进行的辩论、争执。','雍正、乾隆都自负才辩，喜欢跟臣下打～，御笔上谕动辄数百言。★《玉座珠帘》上册','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-326','笔扫千军','bǐ sǎo qiān jūn','形容笔力雄健，如同有横扫千军万马的气势。','～空自负，学传三箧意何施。★元·李庭《吊郭器之二首》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-327','币重言甘','bì zhòng yán gān','币指礼物；厚重。礼物丰厚，言辞好听。指为了能达到某种目的而用财物诱惑。','秦使此来，不是好意，其～，殆诱我也。★明·冯梦龙《东周列国志》第二十九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-328','必不得已','bì bù dé yǐ','必然不能得止。指形势使得非如此不可。表示无可奈何的意思。','布之威怀，革其非心，～，则仗大顺以讨之，出师以征之。★唐·权德舆《世祖封不义侯议》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-329','必也正名','bì yě zhèng míng','指必须按照正统伦理观念和礼仪关系来端正纲纪名分。','～，各司其局，古人所守，某敢忘之？★宋·王谠《唐语林·方正》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-330','必由之路','bì yóu zhī lù','由经由。必定要经过的道路。泛指事物必须遵循的规律或做事必须遵守的法则。','那山离此有六十里远，正是西方～，却有八百里火焰，四周围寸草不生。★明·吴承恩《西游记》第五十九回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-331','毕雨箕风','bì yǔ jī fēng','原指民性如星，星好风雨，比喻庶民喜好人主的恩泽◇为颂扬统治者普施仁政之词。','使雷车电椅，扫荡四方；～，稣舒品物。★前蜀·杜光庭《晋公北帝醮词》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-332','闭关却扫','bì guān què sǎo','却停止；却扫不再清扫车迹，意指谢客。关上大门，扫除车迹。指闭门谢客，不和外界往来。','时来运转，好汉也有惨遭挫败的时候，他就应该～，往日的荣华不必再提。★梁实秋《好汉》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-333','闭关锁国','bì guān suǒ guó','闭关封闭关口；锁封锁。闭关自守，不与外国往来。','严复的译事三难信达雅”为打破～，西学东渐开了先河。★柯灵《序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-334','闭关自守','bì guān zì shǒu','关闭关口，不和外人来往。比喻因循保守，不愿接触外界事物。','而且厦大也太过于～，此后还应该与他大学往还。★鲁迅《两地书》五十八','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-335','闭口捕舌','bì kǒu bǔ shé','犹言畒中捉鳖。比喻敌方已被控制，无法逃脱。','～岂容遁，排山压卵孰与争。★清·钱谦益《送马巽傅归会稽》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-336','闭口无言','bì kǒu wú yán','闭住嘴巴不言语。形容对事不置可否或事情弄僵，自己觉得理亏而无话可讲时的情态。参见闭口不言”。','刘家父女只剩了彼此瞪着，已无话可讲；祥子是～。★老舍《骆驼祥子》十五','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-337','闭门造车','bì mén zào chē','关起门来造车子。比喻脱离实际，只凭主观办事。','自以为～，出而合辙，而门外之辙与其所造之车，果相合否。★严复《救亡决论》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-338','闭门自守','bì mén zì shǒu','①闭门不出，洁身自保。②坚壁不出，严加防守。','朕若～，虏必纵兵大掠。★唐·吴兢《贞观政要·征伐》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-339','闭目塞耳','bì mù sè ěr','堵塞视听。指对外界事物不闻不问或不了解。','设有人～，跣而疾趋，前遇险阻，安有不颠踬者哉！★宋·司马光《遗表》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-340','闭目塞听','bì mù sè tīng','闭上眼睛不看，堵住耳朵不听。形容对外界事物不闻不问。','一个～、同客观外界根本绝缘的人，是无所谓认识的。★毛泽东《实践论》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-341','闭月羞花','bì yuè xiū huā','闭藏。使月亮躲藏，使花儿羞惭。形容女子容貌美丽。','此时鲁小姐卸了浓装，换了几件雅淡衣服，蘧公子举眼细看，真有沉鱼落雁之容，～之貌。★清·吴敬梓《儒林外史》第十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-342','毙而后已','bì ér hòu yǐ','指努力工作或为某一目的奋斗终生，至死才罢休。','公尔忘私，～，是岂寻常所可及哉！★明·田汝成《阿寄传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-343','婢膝奴颜','bì xī nú yán','形容卑躬屈膝谄媚奉承的奴才相。参见奴颜婢膝”。','弟如畏死，则何难媕阿阥冗，～，以求自身之安乐于名场官海之间。★梁启超《复金山中华会馆书》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-344','婢作夫人','bì zuò fū rén','婢侍女；夫人主妇。旧时指在文艺方面虽刻意模仿别人，但才力和作品的规模总赶不上。','不过偶尔学着写，正是～，那里及得到大哥什一。★清·吴趼人《二十年目睹之怪现状》第四十一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-345','敝帚千金','bì zhǒu qiān jīn','一把破扫帚，当千金那样贵重。比喻东西虽不好，但自己十分珍惜。','因循守旧，～的态度是要不得的。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-346','敝帚自珍','bì zhǒu zì zhēn','敝破的，坏的；珍爱惜。把自己家里的破扫帚当成宝贝。比喻东西虽然不好，自己却很珍惜。','但写出以后，却不很爱惜羽毛，有所谓～”的意思。★鲁迅《华盖集·并非闲话〈三〉》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-347','筚路蓝缕','bì lù lán lǚ','筚路柴车；蓝缕破衣服。驾着简陋的车，穿着破烂的衣服去开辟山林。形容创业的艰苦。','～，孙公既开其先；发扬光大，我公宜善其后。★蔡东藩、许廑父第九回《民国通俗演义》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-348','筚门闺窦','bì mén guī dòu','筚门柴门；圭窦上尖下方的圭形门洞。形容穷苦人家的住处。','我不禁暗暗称奇，不料这～中，竟有这等明理女子。★清·吴趼人《二十年目睹之怪现状》第三十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-349','弊绝风清','bì jué fēng qīng','弊坏事；清洁净。贪污、舞弊的事情没有了。形容坏事绝迹，社会风气良好。','从前的赌痞”，现在自己在那里禁赌了，农会势盛的地方和牌一样～。★毛泽东《湖南农民运动考察报告》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-350','弊帚千金','bì zhǒu qiān jīn','对自家的破旧扫帚，也看成价值千金。比喻对己物的珍视。弊，一本作敝”。','里语曰‘家有弊帚，享之千金。’斯不自见之患也。★三国·魏·曹丕《典论·论文》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-351','弊帚自珍','bì zhǒu zì zhén','对自家的破旧扫帚，也看作很珍贵。比喻对己物的珍视。','这是我发表的第一篇作品，虽然幼稚，但～，一直藏着。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-352','碧空如洗','bì kōng rú xǐ','碧空浅蓝色的天空。蓝色的天空明净得像洗过一样。形容天气晴朗。','其时～，有一群大雁鹅正排成人字从高空中飞过。★沈从文《长河·秋（动中有静）》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-353','碧落黄泉','bì luò huáng quán','碧落天上、天界。黄泉地下。天上和地下。泛指宇宙的各个角落。','荷君王不弃，念切思专，～为奴寻遍。★清·洪昻《长生殿·重圆》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-354','蔽日遮天','bì rì zhē tiān','遮住了天空和太阳。形容遮盖的范围非常宽广。','诡难穷，奸莫测，～，一霎分南北。★清·天花藏主人《玉支矶》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-355','避难就易','bì nán jiù yì','就凑近，靠近。躲开难的，去找容易的做。也指做事情先从容易的做起。','有些地方你的确说出了我的弱点，比如你说我～地在手法上取巧。★巴金《生之忏悔·我的自剖》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-356','避强打弱','bì qiáng dǎ ruò','军事用语。在运动战中避开敌人的精锐部队而专拣疲弱的打。','运动战的实行方面，问题是很多的，例如……～，围城打援、佯攻、防空、处在几个敌人之间、超越敌人作战……等等。★毛泽东《中国革命战争的战略问题》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-357','避强击弱','bì qiáng jī ruò','军事用语。在运动战中避开敌人的精锐部队而专拣疲弱的打。','凡攻取之道，必先其易者……奔走之间，可以知其虚实强弱，然后避实击虚，～。★《资治通鉴·后周世宗显德二年》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-358','避实就虚','bì shí jiù xū','指避开敌人的主力，找敌人的弱点进攻。又指谈问题回避要害。','但执笔之际，～，顾彼忌此，实在气闷。★鲁迅《致台静农》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-359','避重就轻','bì zhòng jiù qīng','指回避重的责任，只拣轻的来承担。也指回避要点，只谈无关紧要的事情。','恐将来弄出大祸，所以借了一件失察的事情参的，倒是～的意思，也未可知。★清·曹雪芹《红楼梦》第一百二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-360','髀肉复生','bì ròu fù shēng','髀大腿。因为长久不骑马，大腿上的肉又长起来了。形容长久过着安逸舒适的生活，无所作为。','因见己身～，亦不觉潸然泪下。★明·罗贯中《三国演义》第三十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-361','璧合珠连','bì hé zhū lián','①指日月如合璧，五星如连珠。古人认为是一种显示祥瑞的天象。②比喻众美毕集，相得益彰。','～琰琬垂，蠡应难测管难窥。★清·查慎行《南书房敬观宸翰恭纪》诗之五','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-362','鞭不及腹','biān bù jí fù','及到。原意是鞭子虽长，也不能打马肚子。比喻相隔太远，力量达不到。','则脉络相连，可以应援，邈在鄂渚，岂无～之虑。★《宋史·李宗勉传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-363','鞭辟近里','biān bì jìn lǐ','鞭辟鞭策，激励；里最里层。古代洛阳方言。意指深入剖析，使靠近最里层。形容探求透彻，深入精微。宋儒常用语。','～一言，实吾人顶门针、对症药。★清·李飆《答顾宁人书》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-364','鞭辟入里','biān pì rù lǐ','鞭辟鞭策，激励；里最里层。形容作学问切实。也形容分析透彻，切中要害。','他们的思力不足，不足剖析入微，～。★朱自清《山野掇拾》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-365','鞭长莫及','biān cháng mò jí','及到。原意是鞭子虽长，也不能打马肚子。比喻相隔太远，力量达不到。','除掉腹地里几省外国人～，其余的虽然没有摆在面子上瓜分，暗地里都各有了主子了。★清·李宝嘉《官场现形记》第五十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-366','变本加厉','biàn běn jiā lì','厉猛烈。指比原来更加发展。现指情况变得比本来更加严重。','断句取义是在一句两句里拉出一个两个字来发挥，比起断章取义，真是～了。★朱自清《经典常谈·诗经第四》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-367','变化无常','biàn huà wú cháng','无常没有常态。指事物经常变化，没有规律性。','近来天气～，一会儿晴空万里，一会儿又大雨倾盆。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-368','变生不测','biàn shēng bù cè','变有重大影响的突然变化；不测意外。变故发生于突然之间。','江西省议会及总商会，恐～屡电到鄂，请黎莅任。★蔡东藩、许廑父《民国通俗演义》第二十六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-369','便宜从事','bián yú cóng shì','指可斟酌情势，不拘规制条文，不须请示，自行处理。','汝既为水军都督，可以～，何必禀我？★《三国演义》第四五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-370','便宜施行','bián yú shī xíng','指可斟酌情势，不拘规制条文，不须请示，自行处理。同便宜从事”。','一应军行调度，并听～。★宋·周密《齐东野语·赵信国辞相》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-371','便宜行事','biàn yì xíng shì','便宜方便，适宜。指可以根据实际情况斟酌处理，不必请示。','既然大权交代于你，你就得～。★清·李宝嘉《官场现形记》第十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-372','辨物居方','biàn wù jū fāng','辨别众物的性质、条件等因素，使之各得其所。','夫明哲之士者，威而不慑，困而能通，决嫌定疑，～。★汉徐斡《中论·智行》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-373','辩才无碍','biàn cái wú ài','碍滞碍。本是佛教用语，指菩萨为人说法，义理通达，言辞流利，后泛指口才好，能辩论。','这可见韵高的～，说得顽石点头了。★清·曾朴《孽海花》第十三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-374','标新立异','biāo xīn lì yì','标提出，写明；异不同的，特别的。提出新奇的主张，表示与众不同。','其中典礼集会之词，～固不可，机械陈腐亦不可。★朱自清《钟明〈呕心苦唇录〉序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-375','标新领异','biāo xīn lǐng yì','标提出，写明；异不同的，特别的。提出新奇的主张，表示与众不同。','文定因之以痛哭流涕之怀，发～之论，其去游夏之传，益以远矣。★清·顾炎武《答俞右吉书》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-376','标枝野鹿','biāo zhī yě lù','标枝，树梢之枝，比喻上古之世在上之君恬淡无为；野鹿，比喻在下之民放而自得◇指太古时代。','况欲以过门不入、日昃不食之世，反诸～，其不为西晋者几希？★清·魏源《默觚下·治篇二》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-377','表里如一','biǎo lǐ rú yī','表外表；里内心。表面和内心象一个东西。形容言行和思想完全一致。','我言行一致，～。★郭沫若《屈原》第四幕','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-378','别出机杼','bié chū jī zhù','别另外；机杼织布机，比喻诗文的构思和布局。指写作另辟途径，能够创新。','词人务以相胜，似不若别出机杼。★宋·楼钥《跋李伯和所藏书画薄薄酒二篇》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-379','别出心裁','bié chū xīn cái','别另外；心裁心中的设计、筹划。另有一种构思或设计。指想出的办法与众不同。','只好～，鼓吹女人自杀。★鲁迅《坟·我之节烈观》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-380','别具肺肠','bié jù fèi cháng','比喻人动机不良，故意提出一些与众不同的的奇特的主张。','那老太太却～，非但不惊不吓，还要赶到房里，把席面扫个一空，骂了个无了无休。★清·吴趼人《二十年目睹之怪现状》第七十七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-381','别具慧眼','bié jù huì yǎn','慧聪明，有才智。具有独到眼光，高明的见解。','他～，一眼就看出她的企图。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-382','别具匠心','bié jù jiàng xīn','匠心巧妙的心思。指在技巧和艺术方面具有与众不同的巧妙构思。','《蕃锦集》运用成语，～。★清·陈廷焯《白雨斋词话》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-383','别具只眼','bié jù zhī yǎn','具有独到的眼光和见解。比喻有独到的见解。','然而陈克明教授之所以能～，最主要的原因还在黄梦英有一位表亲”乔张。★茅盾《清明前后》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-384','别开生面','bié kāi shēng miàn','生面新的面目。原意是凌烟阁里的功臣画像本已褪色，经曹将军重画之后才显得有生气。比喻另外创出一种新的形式或局面。','今日林妹妹这五首诗，亦可谓命意新奇，～了。★清·曹雪芹《红楼梦》第六十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-385','别来无恙','bié lái wú yàng','恙病。分别以来一直都很好吗？常用作别后通信或重逢时的问候语。','（蒋）干曰公瑾～？”。★明·罗贯中《三国演义》第四十五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-386','别无长物','bié wú cháng wù','长物多余的东西。除一身之外再没有多余的东西。原指生活俭朴。现形容贫穷。','他们除双手外，～，其经济地位和产业工人相似。★毛泽东《中国社会各阶级的分析》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-387','别有洞天','bié yǒu dòng tiān','洞中另有一个天地。形容风景奇特，引人入胜。','各处尽是画栋雕梁，珠帘绮户，那派艳丽光景，竟是～。★清·李汝珍《镜花缘》第九十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-388','别有肺肠','bié yǒu fèi cháng','别有另有；肺肠指思想。比喻人动机不良，故意提出一些与众不同的的奇特的主张。','那老太太却～，非但不惊不吓，还要赶到房里，把席面扫个一空，骂了个无了无休。★清·吴趼人《二十年目睹之怪现状》第七十七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-389','别有风味','bié yǒu fēng wèi','风味原指美好的口味，引伸为事物的特色。另有一种美好的口味。比喻事物所另外具有的特殊色彩或趣味。','酣眠固不可少，小睡也～的。★朱自清《荷塘月色》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-390','别有天地','bié yǒu tiān dì','天地境界。比喻另有一番境界。形容风景或艺术创作的境界引人入胜。','出了山洞口，只见小桥流水，竹篱茅舍，真是～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-391','宾至如归','bīn zhì rú guī','宾客人；至到；归回到家中。客人到这里就象回到自己家里一样。形容招待客人热情周到。','四方之客，一入鲁境，皆有常供，不至缺乏，～。★明·冯梦龙《东周列国志》第七十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-392','彬彬有礼','bīn bīn yǒu lǐ','彬彬原意为文质兼备的样子，后形容文雅。形容文雅有礼貌的样子。','唤出他两个儿子，兄先弟后，～。★清·李汝珍《镜花缘》第八十三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-393','鬓乱钗横','bìn luàn chāi héng','鬓耳边的头发；钗妇女的首饰，由两股合成。耳边的头发散乱，首饰横在一边。形容妇女睡眠初醒时未梳妆的样子。','争奈一段伤心画不能，肋斗上泪痕粉渍定，没颜色～。★元·乔孟符《两世姻缘》第二折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-394','冰寒于水','bīng hán yú shuǐ','冰比水冷。指后来居上。比喻学生胜过老师。','蘧（道愍）始师章（继伯），～。★唐·张彦远《历代名画记·七·南齐》”','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-395','冰壶秋月','bīng hú qiū yuè','冰壶盛水的玉壶，比喻洁白。比喻洁白明净。多指人的品格。','愿中如～，莹彻无瑕，非吾曹所及。★《宋史·李侗传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-396','冰魂雪魄','bīng hún xuě pò','冰、雪如冰的透明，雪的洁白。比喻人品质高尚纯洁。','广寒宫里长征药，医得～回。★宋·陆游《北坡梅》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-397','冰肌玉骨','bīng jī yù gǔ','冰晶莹。肌骨如同冰玉一般。形容女子肌肤莹洁光滑。','换却～胎，丹心吐出异香来。★元·张寿卿《红梨花》第二折','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-398','冰清玉洁','bīng qīng yù jié','象冰那样清澈透明，象玉那样洁白无瑕。比喻人的操行清白（多用于女子）。','我这一去～，干事回还，管着你们喝采他。★元·无名氏《陈州粜米》楔子','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-399','冰清玉润','bīng qīng yù rùn','润滋润。象冰一样晶莹，如玉一般润泽。原指晋乐广卫玠翁婿俩操行洁白◇常比喻人的品格高洁。','他是～，怎便肯随波逐尘。★明·高濂《玉簪记》第三十出','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-400','冰山易倒','bīng shān yì dǎo','冰山遇到太阳就消溶，容易倒塌。比喻不能长久依赖的靠山。','人们纷纷投靠宰相杨国忠，张彖却认为～，决不依附权贵。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-401','冰消瓦解','bīng xiāo wǎ jiě','冰一样地消融，瓦一样地分解。比喻完全消失或彻底崩溃。','韩夫人喜不自胜，将一天愁闷，已～了。★明·冯梦龙《醒世恒言》卷十三','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-402','兵不血刃','bīng bù xuè rèn','兵武器；刃刀剑等的锋利部分。兵器上没有沾上血。形容未经战斗就轻易取得了胜利。','～，就平了广西省多年的乱党。★清·张春帆《宦海》第七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-403','兵不厌诈','bīng bù yàn zhà','厌嫌恶；诈欺骗。作战时尽可能地用假象迷惑敌人以取得胜利。','若说～，诸葛亦无如此之阵图，若说幻不厌深，偃师亦无如此之机械。★元·王实甫《西厢记》第三本第二折金圣叹批','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-404','兵车之会','bīng chē zhī huì','春秋时齐桓公争霸，屡次与诸侯会盟，其中在鲁僖公年间的四次，齐国带有军队，你为兵车之会”。','寡人用～三，衣裳之会六，九合诸侯，一匡天下。★明·冯梦龙《东周列国志》第二十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-405','兵出无名','bīng chū wú míng','出兵没有正当理由。亦泛指行事无正当理由。同师出无名”','昔赤眉、黄巾横逆宇宙，所以一旦败亡者，正以～，聚而为乱。★《晋书·石勒传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-406','兵戈扰攘','bīng gē rǎo rǎng','兵戈武器，指战争；扰攘纷乱。形容战争时期社会秩序的动荡混乱。','那老母原是～中看见杀儿掠女，掠坏了再苏的。★明·凌濛初《初刻拍案惊奇》卷二十二','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-407','兵荒马乱','bīng huāng mǎ luàn','荒、乱指社会秩序不安定。形容战争期间社会混乱不安的景象。','此时四处～，朝秦暮楚，我勉强做了一部《旧唐书》，那里还有闲情逸志弄这笔墨。”★清·李汝珍《镜花缘》第一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-408','兵精粮足','bīng jīng liáng zú','兵士精壮，粮草充足。形容军力强盛，战备充分。','他久镇河北，～，自立旗号，不服隋朝所管。★清·无名氏《说唐》第二十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-409','兵连祸结','bīng lián huò jié','兵战争；连接连；结相联。战争接连不断，带来了无穷的灾祸。','～，涂炭平民，耗损国内，悔之晚矣。★明·刘基《前江淮都转运盐使宋公政绩纪》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-410','兵临城下','bīng lín chéng xià','敌军已来到自己的城墙下面。比喻情势十分危急。','若侯～，将至壕边，然后拒敌，事已迟矣。★明·罗贯中《三国演义》第三十一回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-411','兵强马壮','bīng qiáng mǎ zhuàng','兵力强盛，战马健壮。形容军队实力强，富有战斗力。','时孔明～，粮草丰足，所用之物，一切完备，正要出师。★明·罗贯中《三国演义》第九十七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-412','掤扒吊拷','bīng bā diào kǎo','强行脱去衣服，捆绑并吊起来拷打。同绷扒吊拷”。','大尹升堂，验着衣领针线是实，明知无枉，喝教‘用起刑来！’令招实情。～，备受苦楚，这些顽皮赖肉只不肯招。★明·凌濛初《二刻拍案惊奇》卷五','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-413','并驾齐驱','bìng jià qí qū','并驾几匹马并排拉着一辆车；齐驱一齐快跑。并排套着的几匹马一齐快跑。比喻彼此的力量或才能不分高下。','若让我估量这本书的总价值，我以为只逊于《红楼梦》一筹，与《儒林外史》是可以～的。★朱自清《歧路灯》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-414','并日而食','bìng rì ér shí','并日两天合并成一天。不能天天得食，两天三天才能得一天的粮食。形容生活穷困。','思惟北征，宜先入南，故五月渡泸，深入不毛，～，臣非不自惜也，顾王业不可偏安于蜀都。★三国·蜀·诸葛亮《后出师表》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-415','病从口入','bìng cóng kǒu rù','疾病多是由食物传染。比喻应该注意饮食卫生。','我们要讲究饮食卫生，防止～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-416','病民蛊国','bìng mín gǔ guó','病损坏，祸害；蛊相传为人工培养的毒虫，引伸为毒害ˇ人民、害国家。','吾辈～不能仇，现在之执法者也。★清·纪昀《阅微草堂笔记》卷五','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-417','病入膏肓','bìng rù gāo huāng','膏肓古人把心尖脂肪叫膏”，心脏与膈膜之间叫肓”。形容病情十分严重，无法医治。比喻事情到了无法挽救的地步。','吾观刘琦过于酒色，～，今见面黄羸瘦，气喘呕血，不过半年，其人必死。★明·罗贯中《三国演义》第五十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-418','病在膏肓','bìng zài gāo huāng','比喻事情到了无法挽救的地步。同病入膏肓”。','便遇秦和医国手，只恐他～怎救？★明邵璨《香囊记·问卜》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-419','拨乱反正','bō luàn fǎn zhèng','拨治理；乱指乱世；反通返”，回复。消除混乱局面，恢复正常秩序。','今天运将转，不过数十年，真人当出，～。★明·冯梦龙《古今小说》卷三十二','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-420','拨乱反治','bō luàn fǎn zhì','犹拨乱反正。指消除混乱局面，恢复正常秩序。','夫～，苟无非常之才，其力固难以及远也。★清·何焯《义门读书记·左传一》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-421','拨云睹日','bō yún dǔ rì','拨开云彩看见太阳。形容受到启发，思想豁然开朗，或比喻见到光明，大有希望。同拨云见日”。','自别兄长台颜，一向有失听教，今得一见，如～。★元·王实甫《西厢记》第二本楔子','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-422','拨云见日','bō yún jiàn rì','拨开乌云见到太阳。比喻冲破黑暗见到光明。也比喻疑团消除，心里顿时明白。','晚生得蒙老先生指教，如～，感激不尽。（清·吴敬梓《儒林外史》第三十九回）','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-423','波谲云诡','bō jué yún guǐ','谲诡怪异，变化∶象云彩和水波那样，形态不可捉摸。原形容房屋构造就象云彩、波浪一样千姿百态◇多形容事物变幻莫测。','这其间的悲欢离合，～，令人在冷静沉默中回想起来，抚今追昔，实不胜其感慨系之.★邹韬奋《抗战以来·开匙》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-424','波澜老成','bō lán lǎo chéng','波澜波涛，形容文章多起伏；老成指文章很老练。形容文章气势雄壮，语句老练。','情辞斐亹，～，吾敬孙君宇台。★清·王晫《今世说·品藻》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-425','波澜壮阔','bō lán zhuàng kuò','原形容水面辽阔。现比喻声势雄壮或规模巨大。','七言诗须～，顿挫激昂，大开开阖耳。★清·郎廷槐《师友诗传续录》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-426','剥床及肤','bō chuáng jí fū','剥六十四卦之一，坤下艮上，意即剥落、烂；及到。原指损害及于肌肤◇形容迫切的灾害或深切的痛苦。','～，其忧岂不在民乎！★宋·陈亮《义乌县减酒额记》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-427','剥肤椎髓','bō fū chuí suǐ','剥剥去；肤皮肤；椎捶击。剥人皮肤，敲人骨髓。比喻极其残酷地压榨和剥削。','世方以阿意顺旨为贤，～为能。★明·焦竑《玉堂丛语·政事》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-428','播穅眯目','bō kāng mǐ mù','散布糠屑以迷人目。比喻被外物蒙蔽而迷失方向。','夫意之所蔽以恶为美者多矣，何特眇倡之事哉？传曰‘～，则天地四方易位。’余尝三复其言而悲之。★宋·秦观《眇倡传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-429','伯仲之间','bó zhòng zhī jiān','伯仲兄弟排行的次第，伯是老大，仲是老二；间中间。比喻差不多，难分优劣。','～见伊吕，指挥若定失萧曹。★唐·杜甫《咏怀古迹》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-430','勃然变色','bó rán biàn sè','勃然突然地。变色变了脸色。突然生气，变了脸色。','重耳～，搁杯不饮。★明·冯梦龙《东周列国志》第三十四回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-431','博采众长','bó cǎi zhòng cháng','博采广泛搜集采纳。从多方面吸取各家的长处。','他对学生、画友，从不以我画线，而是主张～，自立门户。★黄胄《怀念望云老师》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-432','博古通今','bó gǔ tōng jīn','通通晓；博广博，知道得多。对古代的事知道得很多，并且通晓现代的事情。形容知识丰富。','你向有才女之名，最是～。★清·李汝珍《镜花缘》第五回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-433','博硕肥腯','bó shuò féi tú','博硕形状大；腯音‘途’，肥壮。指六畜肥壮。','家有水牛一，博硕肥途，爱之特甚。★清·淮阴百一居士《壶天录》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-434','博文约礼','bó wén yuè lǐ','博金我，广；约约束。广求学问，恪守礼法。','～，讵穷于钻仰也。★清·王闿运《八代文粹序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-435','博闻多识','bó wén duō shí','博广博；闻见闻；识学识。知识丰富，见闻广博。','公子生长中原，～，必知此兽之名。★明·冯梦龙《东周列国志》第35回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-436','补苴罅漏','bǔ jū xià lòu','苴鞋底的草垫；罅缝隙。补好裂缝，堵住漏洞。比喻弥补事物的缺陷。','～，经纬万端。来日之难，培于往昔。★蔡东藩、许廑父《民国通俗演义》第七十七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-437','补牢顾犬','bǔ láo gù quǎn','丢失了羊，才修补羊圈；见了野兔，才回头唤狗去追捕。比喻对出现的失误，及时设法补救。','及待开厂制办，～，已觉其迟。★清·左宗棠《请拓增船炮大厂疏》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-438','补偏救弊','bǔ piān jiù bì','偏偏差；弊赞美。补救偏差漏洞，纠正缺点错误。','苟不自其本页图之，则亦仅能～，偷为一时之治而已矣。★严复《原强》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-439','补阙拾遗','bǔ quē shí yí','阙通缺”，缺失。拾遗补录遗漏。补录缺失遗漏的内容。','其次扬清激浊，能～。★《明史·孙磐传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-440','补天浴日','bǔ tiān yù rì','这是指女娲炼五色石补天和羲和给太阳洗澡两个神话故事◇用来比喻人有战胜自然的能力。也形容伟大的功业。','反听刘隗刁协之徒，窃弄威柄，将我～之功，弃而不录，思之不能无怨也。★明·朱鼎《玉镜合记·新亭流涕》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-441','哺糟歠醨','bǔ zāo chuò lí','比喻效法时俗，随波逐流。亦作哺糟啜醨”。','～，俯同妄作，披褐怀玉，无由自陈。★唐·刘知幾《史通·核才》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-442','捕风捉影','bǔ fēng zhuō yǐng','风和影子都是抓不着的。比喻说话做事丝毫没有事实根据。','若被黜者一一求其所以得罪之故，～，捏造流言。★明·张居正《乞鉴别忠邪以定国上疏》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-443','捕影系风','bǔ yǐng xì fēng','风和影子都是抓不着的。比喻说话做事丝毫没有事实根据。','于是连兵十数年，国削民乏，渺然视太平之象，更若～。★南唐·史虚白《钓矶立谈》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-444','不按君臣','bù àn jūn chén','中医处方，以君臣相配为原则。君是主药，臣是辅药。不按君臣，就是违反药理，胡乱用药。引申为使用毒药的隐语。','宋四公怀中取出酸馅，着些个～作怪的药，入在里面。★《古今小说·宋四公大闹禁魂张》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-445','不卑不亢','bù bēi bù kàng','卑低、自卑；亢高傲。指对人有恰当的分寸，既不低声下气，也不傲慢自大。','老张虽着急，可是龙树古～的支应，使老张无可发作。★老舍《老张的哲学》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-446','不避斧钺','bù bì fǔ yuè','斧钺古代的兵器。不躲避斧钺之类的兵器。形容将士英勇无畏，或烈士忠义不屈。','臣向来不以面从为忠，故今日～，直言苦谏。★姚雪垠《李自成》第二卷第三十二章','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-447','不辨菽麦','bù biàn shū mài','菽豆子。分不清哪是豆子，哪是麦子。形容愚笨无知◇形容缺乏实际生产知识。','世间也尽有～的人。★郭沫若《银杏》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-448','不测之祸','bù cè zhī huò','测揣度，预测。无法揣测的祸患。多指牢狱或杀身之祸。','先生几蹈～。★清·汪琬《送魏光禄归蔚州序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-449','不臣之心','bù chén zhī xīn','不臣不守臣子的本分，封建社会中不忠君。意指不忠君的思想◇也指犯上作乱的野心。','后又结托朝贵，遂任显官，统西州大军二十万，常有～。★明·罗贯中《三国演义》第三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-450','不成体统','bù chéng tǐ tǒng','体统格局，规矩。指言行没有规矩，不成样子。','此时官厅上乱烘烘的，闹了个～。★清·吴趼人《二十年目睹之怪现状》第二十七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-451','不逞之徒','bù chěng zhī tú','不逞不得志，不如意；徒人（含贬义）。因心怀不满而闹事捣乱的人。','如有～假托民军，借端扰害治安，即为人民公敌。★蔡东藩、许廑父《民国通俗演义》第六十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-452','不痴不聋','bù chī bù lóng','人不傻，耳朵也不聋。常与不成姑公”连用，意为不故作痴呆，不装聋作哑，就不能当阿婆阿公。形容长辈要宽宏大量。','鄙谚有之～，不作家翁。”★《资治通鉴·唐纪代宗大历二年》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-453','不齿于人','bù chǐ yú rén','齿象牙齿一样排列。不能列于人类。指被人看不起。','燕人马植，本辽大族，仕至光禄卿，行污而内乱，～。★清·毕沅《续资治通鉴·宋纪·徽宗政和元年》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-454','不耻下问','bù chǐ xià wèn','乐于向学问或地位比自己低的人学习，而不觉得不好意思。','阁下既～，弟先须请教宗旨何如？★清·刘鹗《老残游记》第七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-455','不耻最后','bù chǐ zuì hòu','因为跑到最后而感到可耻。比喻凡是只要坚持到底，就能达到目的。','记得韩非子曾经教人以竞马的要妙，其一是‘～’。★鲁迅《华盖集·补白》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-456','不啻天渊','bù chì tiān yuān','不啻无异于。渊深潭。无异于从云天之上到深潭之底。比喻差别极大。','比那辛亥革命，直～远隔呢。★蔡东藩、许廑父《民国通俗演义》第二十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-457','不出所料','bù chū suǒ liào','事由变化，在预料之中。形容原先预料的准确。','果然～，”这样的一念闪过校长先生的心头。(叶圣陶《一篇宣言》)','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-458','不揣冒昧','bù chuǎi mào mèi','揣估量，考虑。用于没有慎重考虑就轻率行事的客气话。','又看到日本学界也每每用汉文出书，我真是～，竟想把我的论著也拿去尝试。★郭沫若《海涛集·我是中国人》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-459','不辞而别','bù cí ér bié','辞告辞；别离别。没有告辞就离开了。或悄悄溜走了。','于是，大家想不辞而别。★老舍《不成问题的问题》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-460','不辞劳苦','bù cí láo kǔ','辞推托；劳苦劳累辛苦。不逃避劳累辛苦。形容人不怕吃苦，毅力强。','真正难得的，是她那不会厌倦的同情和～的服务。★朱自清《刘云波女医师》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-461','不次之迁','bù cì zhī qiān','次顺序，等第；迁官位升迁。比喻超出常规的提升官级。','果能使地方安静，虽无～，要亦不至于冻馁。★清·刘鹗《老残游记》第七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-462','不打自招','bù dǎ zì zhāo','招招供。旧指没有用刑就招供。比喻做了坏事或有坏的意图自我暴露出来。','但是我还要说重庆发言人是个蠢猪，他～，向人国人民泄露了日本帝国主义的计划。★毛泽东《为皖南事变发表的命令和谈话》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-463','不当人子','bù dāng rén zǐ','表示歉意或感谢的话，意思是罪过，不敢当。','我们都是烟火邻居，遇着这样大事，理该效劳。却又还破费老师父，～。★清·吴敬梓《儒林外史》第二十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-464','不得不尔','bù dé bù ěr','尔如此。不得不这样。表示为环境所迫或有难言之隐而无可奈何。','这是事势相逼，～。★清·吴敬梓《儒林外史》第四十六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-465','不得人心','bù dé rén xīn','心心愿，愿望。得不到群众的支持拥护；得不到众人的好评。','只恨那婆子～，劈手夺了他宝贝去。★清·曾朴《孽海花》第七回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-466','不得要领','bù dé yào lǐng','要古腰”字；领衣领。要领比喻关键。抓不住要领或关键。','我又无拳无勇，真没办法，在手头的只有笔墨，能写这封信一类的～的东西而已。★鲁迅《两地书》八','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-467','不登大雅','bù dēng dà yǎ','大雅高贵典雅。不能登上高雅的厅堂。形容某些不被人看重的、粗俗”的事物（多指文艺作品）。','按照老看法，这类书至多只能指示童蒙，～。★朱自清《序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-468','不动声色','bù dòng shēng sè','声言谈；色脸色。在紧急情况下，说话、神态仍跟平时一样没有变化。形容非常镇静。','他也～，勤勤慎慎办他的公事。★清·李宝嘉《官场现形记》第十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-469','不二法门','bù èr fǎ mén','不二指不是两极端；法门佧行入道的门径。原为佛家语，意为直接入道，不可言传的法门◇比喻最好的或独一无二的方法。','历观战史，水战用火攻，是颠扑不破的～。★高阳《清宫外史》下册','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-470','不分彼此','bù fēn bǐ cǐ','彼那，对方；此这，我方。不分这个和那个。形容关系密切，交情深厚。','他就是我，我就是他，我俩原是～的。★蔡东藩、许廑父《民国通俗演义》第一百三十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-471','不分轩轾','bù fēn xuān zhì','不分高下、轻重。比喻对待二者的态度或看法差不多。','但先入之言，容易见听，如果有两个人在慈禧太后心目中～，那时想起溥伦的话，关系出入就太大了。★高阳《胭脂井》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-472','不分畛域','bù fēn zhěn yù','畛域范围，界限。不分界限、范围。也比喻不分彼此。','我们善堂是～的，往时各省有了灾荒，没一处不去赈济。★清·黄小配《廿载繁华梦》第二十八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-473','不丰不杀','bù fēng bù shā','丰厚；杀减少。不奢侈也不啬俭。不增加也不减少。','宫门费”～，按股匀分，倒也相安无事。★高阳《胭脂井》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-474','不伏烧埋','bù fú shāo mái','伏屈服；烧埋烧埋银钱，旧时官府向杀人犯追缴赔给死者家属的埋葬费。比喻不伏罪或不听劝解。','我又不敢当厅抵赖，恰待分说，又道咱家～。★《元曲选·争报恩》二','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-475','不改其乐','bù gǎi qí lè','不改变自有的快乐。指处于困苦的境况仍然很快乐。','（孔子）称赞颜回吃喝不够，‘～’。★朱自清《论吃饭》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-476','不甘寂寞','bù gān jì mò','甘甘心；寂寞孤寂、冷落。形容不甘心被冷落或急于想参与某件事情。','从内务府垮下来的文锡，一向～。★高阳《清宫外史》下册','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-477','不尴不尬','bù gān bù gà','比喻左右为难，不好处理。也形容样子别扭。','外甥女少不得的是我们养着，牛姑爷也该做出一个主意来，只管～住着，也不是事。★清·吴敬梓《儒林外史》第二十二回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-478','不敢高攀','bù gǎn gāo pān','不敢跟社会地位比自己高的人交朋友或结亲戚。','他那种人我们是～的。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-479','不敢告劳','bù gǎn gào láo','努力做事，不诉说自己的劳苦。比喻勤勤恳恳，不辞辛劳（多用在自己表示谦虚）。','凡所实施，光明正大。艰苦奋斗，～。★《毛泽东选集·陕甘宁边区政府、第八路军后方留守处布告》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-480','不攻自破','bù gōng zì pò','无须攻击，自己就会破灭。形容论点站不住脚，经不起反驳或攻击。','郢都无主，～。★明·冯梦龙《东周列国志》第七十六回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-481','不共戴天','bù gòng dài tiān','戴加在头上或用头顶着。不愿和仇敌在一个天底下并存。形容仇恨极深。','这亘古未有的壮举，像一柄锋利的匕首，直刺～的死敌。”★齐怀《刑场上的婚礼》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-482','不苟言笑','bù gǒu yán xiào','苟苟且，随便。不随便说笑。形容态度庄重严肃。','且说这位郑伯才君，单名一个雄字，乃是湖南湘潭县人，向来是个讲宋学的，方领矩步，～。★清·梁启超《新中国未来记》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-483','不古不今','bù gǔ bù jīn','指事物不正常，古代现代都不曾有过。原讥讽人学无所得却故作诡异◇常比喻折衷。','遥见双炬，疑为虎目，至前则官役数人，衣冠～。★清·纪昀《阅微草堂笔记》卷十八','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-484','不顾死活','bù gù sǐ huó','顾顾念，考虑。连生死也不考虑了。形容拼命蛮干，不顾一切。','他们更希望有经验的人来领导他们，他们原意～地保卫家乡。★巴金《火》第二部十','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-485','不关痛痒','bù guān tòng yǎng','痛痒比喻疾苦或紧要的事。比喻切身相关的事。指与自身利害没有关系。','这里虽还有两三个老婆子，都是～的，见李妈走了，也都悄悄的自寻方便去了。★清·曹雪芹《红楼梦》第八回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-486','不过尔尔','bù guò ěr ěr','尔（前）如此，这样；尔（后）通耳”，罢了。不过这样罢了。有轻视人的意思。','白狼竟露布讨袁，斥为神奸国贼，文辞工炼，相传为陈琳讨曹，～。★蔡东藩、许廑父《民国通俗演义》第四十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-487','不寒而栗','bù hán ér lì','栗畏惧，发抖。不冷而发抖。形容非常恐惧。','岂果脂粉之气，不势而威？胡乃肮脏之身，～。★清·蒲松龄《聊斋志异·马介甫》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-488','不合时宜','bù hé shí yí','时宜当时的需要和潮流。不适合时代形势的需要。也指不合世俗习尚。','闻得他因～，权势不容，竟投到这里来。★清·曹雪芹《红楼梦》第六十三回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-489','不慌不忙','bù huāng bù máng','不慌张，不忙乱。形容态度镇定，或办事稳重、踏实。','公路在山上盘旋，车子～地打着圈子。★巴金《旅途杂记·成渝路上》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-490','不遑宁处','bù huáng níng chǔ','遑闲暇。没有闲暇的时候。指忙于应付繁重或紧急的事情。','频繁上命，徒想报恩，驰骤下寮，～。★唐·张鷟《游仙窟》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-491','不遑宁息','bù huáng níng xī','没有闲暇的时间过安宁的日子。指忙于应付繁重或紧急的事务。同不遑宁处”。','微臣所以叩心绝气，忘寝与食，雕肝焦虑，～者也。★唐·房玄龄《晋书·凉武昭王传》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-492','不惑之年','bù huò zhī nián','不惑遇到事情能明辨不疑。以此作为40岁的代称。','他大学毕业年仅20，而光阴飞转，很快已近～了。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-493','不羁之才','bù jī zhī cái','羁马笼头，比喻约束。非凡的、不可拘束的才能。','余与稽康、吕安居止接近，其人并有～。★晋·向秀《思旧赋序》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-494','不即不离','bù jí bù lí','即接近，靠近；离疏远，离开。指对人既不接近，也不疏远。多指对人似亲非亲、似疏非疏的关系。','刘本人打着保境安民的旗号，隐隐地以湖北的政治中心自命，对于南北两方都采取着～的态度。★郭沫若《革命春秋·北伐途次》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-495','不急之务','bù jí zhī wù','急急迫，要紧；务事情。无关紧要的或不急于做的事情。','长吏迫于崔科，视学舍为～。★清·朱彝尊《衢州府西安县重修学记》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-496','不假思索','bù jiǎ sī suǒ','假假借，依靠。形容做事答话敏捷、熟练，用不着考虑。','华安～，援笔立就，手捧所做呈上。★明·冯梦龙《警世通言》卷二十六','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-497','不间不界','bù gān bù gà','比喻左右为难，不好处理。也形容样子别扭。同不尴不尬”。','道如大路皆可遵，～难为人。★宋·吴泳《赋半斋送张清分教嘉定》诗','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-498','不见经传','bù jiàn jīng zhuàn','经传指被古人尊崇为典范的著作。经传上没有记载◇常指人没有名声或论述没有根据。','我们住的小胡同，连轿车也进不来，一向～。★老舍《吐了一口气》','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-499','不教而杀','bù jiào ér shā','教教育；杀处罚，杀死。不警告就处死。指事先不教育人，一犯错误就加以惩罚。','对待犯错误的人应当采取治病救人的方针，而不应该～。','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft'),
('source-500','不教而诛','bù jiào ér zhū','教教育；诛处罚，杀死。不警告就处死。指事先不教育人，一犯错误就加以惩罚。','大人限他们三个月叫他们戒烟，宽之以期限，动之以厉害，不忍～。★清·李宝嘉《官场现形记》第二十回','待分类','crazywhalecc/idiom-database · MIT · 数据说明来自 pwxcoo/chinese-xinhua；原始文件：https://raw.githubusercontent.com/crazywhalecc/idiom-database/master/data/idiom.json','待校审','draft')
insert into public.questions (id,stem,options,answer,explanation,source,source_ref,difficulty,status,content_status,reviewed_at) values
('question-001','但也有少数意志薄弱的……逐步上当，终至堕入______。★《上饶集中营·炼狱杂记》','["阿鼻地狱","爱惜羽毛","把素持斋","抱残守阙"]'::jsonb,0,'释义：阿鼻梵语的译音，意译为无间”，即痛苦无有间断之意。常用来比喻黑暗的社会和严酷的牢狱。又比喻无法摆脱的极其痛苦的境地。。原始资料成语：阿鼻地狱。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','进阶','published','imported',null),
('question-002','既然如此，你我两个，便学个不痴不聋的______。★《儿女英雄传》二三回','["暧昧不明","阿姑阿翁","罢黜百家","抱成一团"]'::jsonb,1,'释义：阿名词的前缀。姑丈夫的母亲。翁丈夫的父亲。指公公婆婆。。原始资料成语：阿姑阿翁。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','基础','published','imported',null),
('question-003','______原相配，太其玉镜宁无时？★明·周履靖《锦笺记·诒婚》','["暧昧之情","霸王别姬","阿娇金屋","抱打不平"]'::jsonb,2,'释义：阿娇指汉武帝刘彻的姑母（长公主刘娇）的女儿。原指汉武帝刘彻要用金屋接纳阿娇为妇。这里泛指美丽高贵的女子。。原始资料成语：阿娇金屋。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','基础','published','imported',null),
('question-004','在德国无论______见面，一律互相举手高喊希特勒万岁”。★邹韬奋《法西斯作风的罪恶》','["安不忘危","白白朱朱","抱负不凡","阿猫阿狗"]'::jsonb,3,'释义：旧时人们常用的小名。引申为任何轻贱的，不值得重视的人或著作。。原始资料成语：阿猫阿狗。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','基础','published','imported',null),
('question-005','和尚念经，______。','["阿弥陀佛","安步当车","白璧青蝇","抱关击柝"]'::jsonb,0,'释义：佛教语，信佛的人用作口头诵颂的佛号，表示祈祷祝福或感谢神灵的意思。。原始资料成语：阿弥陀佛。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','基础','published','imported',null),
('question-006','生前不曾修福，死堕______。★《敦煌变文集·妙法莲花经讲经文》','["安常处顺","阿毗地狱","白璧三献","抱恨终天"]'::jsonb,1,'释义：阿毗梵语的译音，意译为无间”，即痛苦无有间断之意。常用来比喻黑暗的社会和严酷的牢狱。又比喻无法摆脱的极其痛苦的境地。。原始资料成语：阿毗地狱。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','进阶','published','imported',null),
('question-007','吾何能______为？★鲁迅《坟·摩罗诗力说》','["安常守故","白璧微瑕","阿其所好","抱火厝薪"]'::jsonb,2,'释义：阿曲从；其他的；好爱好。指为取得某人的好感而迎合他的爱好。。原始资料成语：阿其所好。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','基础','published','imported',null),
('question-008','其时京师有一流棍，名叫李光，专一______，谄事令孜。★明·凌濛初《初刻拍案惊奇》卷二十二','["安常习故","白璧无瑕","抱火卧薪","阿谀逢迎"]'::jsonb,3,'释义：阿谀用言语恭维别人；逢迎迎合别人的心意。奉承，拍马，讨好别人。。原始资料成语：阿谀逢迎。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','基础','published','imported',null),
('question-009','且王髈等______，蔽贤窃位。★明·冯梦龙《东周列国志》','["阿谀取容","安车蒲轮","白发丹心","抱头鼠窜"]'::jsonb,0,'释义：阿谀曲意逢迎；取容取悦于人。谄媚他人，以取得其喜悦。。原始资料成语：阿谀取容。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','基础','published','imported',null),
('question-010','咱人有子方知不孝娘，岂不问______情肠！★元·无名氏《小张屠》第一折','["安堵如故","哀哀父母","白发千丈","豹死留皮"]'::jsonb,1,'释义：可哀呀可哀，我的父母啊！原指古时在暴政下的人民终年在外服劳役，对父母病痛、老死不能照料而悲哀。。原始资料成语：哀哀父母。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','基础','published','imported',null),
('question-011','那安太太进门，一眼便看见姑娘，______的跪在那里……便一直的奔了姑娘去。★清·文康《儿女英雄传》第二十回','["安分守己","白圭之玷","哀哀欲绝","鲍鱼之肆"]'::jsonb,2,'释义：哀哀极度悲哀；绝断气，死。形容极其悲痛。。原始资料成语：哀哀欲绝。','开源成语资料改编原创训练题','https://github.com/crazywhalecc/idiom-database/blob/master/data/idiom.json；依据原始释义和例句改编，非官方真题','进阶','published','imported',null),
